export default [{"id":245,"question":"ما المسموح به بأن يراه الخطيبُ من خطيبته عند طلبه رؤيته؟","title":"ما مقدار ما يراه الخاطب ممن يريد خطبتها؟","answer":"الجواب: في هذا خلافٌ بين أهل العلم، والأحوط في هذا أنه يكفي الوجه والكفَّان والقدمان، وإن رأى الشعر فلا بأس، لا نرى مانعًا؛ لأنَّ الشعر قد يظهر للمحارم وغير المحارم من الزوج، المقصود أنَّ هذا لا بأس به، لكن إذا اكتفت بوجهها وكفّيها وقدميها فلا بأس، ولو رأى من الشعر فلا حرج؛ لأنه قد يظهر في بعض الأحيان.","link":"https://binbaz.org.sa/fatwas/4134/ما-مقدار-ما-يراه-الخاطب-ممن-يريد-خطبتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0287.mp3","categories":["الخِطْبَة والاختيار ","الحكم على الأحاديث"]},{"id":514,"question":"هل للمرأة أن تنظر إلى الرجل (الخاطب)؟","title":"حكم نظر الفتاة إلى خاطبها","answer":"الجواب: نعم إذا كان خطبها لها أن تنظر؛ لأن هذا من مصلحتها، وهو ما جاء في الحديث لكن من حيث المعنى، من حيث المعنى لا بأس، لكن ما أعلم فيه شيئًا.\n(دروس شرح بلوغ المرام، كتاب النكاح)","link":"https://binbaz.org.sa/fatwas/6344/حكم-نظر-الفتاة-الى-خاطبها","audio":"https://files.zadapps.info/binbaz.org.sa/maram079 - 03 - .mp3","categories":["الخِطْبَة والاختيار ","الحكم على الأحاديث"]},{"id":515,"question":"الخطيب هل له  أن يرتّل الثلاث آيات في خطبة الحاجة؟","title":"حكم ترتيل الآيات الثلاث في خطبة الحاجة","answer":"الجواب: كما جاء في الحديث: يقرأ آل عمران ثم آية النساء، ثم آية الأحزاب، يقرأها قراءة عادية أو مرتّلة، كله طيب.\n(دروس شرح بلوغ المرام، كتاب النكاح)","link":"https://binbaz.org.sa/fatwas/6345/حكم-ترتيل-الايات-الثلاث-في-خطبة-الحاجة","audio":"https://files.zadapps.info/binbaz.org.sa/maram080 - 03 - .mp3","categories":["الخِطْبَة والاختيار ","الحكم على الأحاديث"]},{"id":516,"question":"صحة الحديث أن النبي ﷺ بعث أم سليم قال: انظري إلى عرقوبها وشمي معاطفها؟","title":"هل صح حديث: \"انظري إلى عرقوبها..\"؟","answer":"الجواب: ما أتذكر هذا.\n(دروس شرح بلوغ المرام، كتاب النكاح)","link":"https://binbaz.org.sa/fatwas/6346/هل-صح-حديث-انظري-الى-عرقوبها","audio":"https://files.zadapps.info/binbaz.org.sa/maram082  - 01 -  Start.mp3","categories":["الخِطْبَة والاختيار "]},{"id":517,"question":"خطبة الحاجة واجبة في العقد أو سُنة؟","title":"حكم خطبة الحاجة في عقد النكاح","answer":"الجواب: سُنة مستحبة؛ النبي ﷺ في قصة المرأة الواهبة زوجها بدون خطبة لما جاءه إنسان يخطبها قال: التمس خاتمًا فلم يجد قال: زوجتكها بما معك من القرآن ولم يذكر الخطبة.\n(دروس شرح بلوغ المرام، كتاب النكاح)","link":"https://binbaz.org.sa/fatwas/6347/حكم-خطبة-الحاجة-في-عقد-النكاح","audio":"https://files.zadapps.info/binbaz.org.sa/maram082  - 01 -  Start.mp3","categories":["الخِطْبَة والاختيار "]},{"id":518,"question":"محمد بن مسلمة قال: إذا ألقى الله في قلب امرئ منكم خطبة امرأة فهل ينظر قبل الخطبة أم بعد الخطبة؟","title":"هل النظر للمخطوبة قبل الخطبة أم بعدها؟","answer":"الجواب: ينظر قبل أن يخطبها.\n(دروس شرح بلوغ المرام، كتاب النكاح)","link":"https://binbaz.org.sa/fatwas/6348/هل-النظر-للمخطوبة-قبل-الخطبة-ام-بعدها","audio":"https://files.zadapps.info/binbaz.org.sa/maram083 - 01 -  Start.mp3","categories":["الخِطْبَة والاختيار "]},{"id":519,"question":"هل يجوز للمرأة أن تعرض نفسها؟","title":"حكم عرض المرأة نفسها للزواج","answer":"الجواب: لا بأس، مثل ما عرضت الواهبة.\n(دروس شرح بلوغ المرام، كتاب النكاح)","link":"https://binbaz.org.sa/fatwas/6349/حكم-عرض-المراة-نفسها-للزواج","audio":"https://files.zadapps.info/binbaz.org.sa/maram084 - 03 - .mp3","categories":["الخِطْبَة والاختيار "]},{"id":521,"question":"إذا خطب الفاسق هل للعفيف أن يخطب على خِطبته؟","title":"هل تجوز الخِطبة على خِطبة الفاسق؟","answer":"الجواب: لا، لا يخطب على خطبته، يجوز تزويج الفاسق إذا كان مكافئًا.\n(دروس شرح بلوغ المرام، كتاب النكاح)","link":"https://binbaz.org.sa/fatwas/6351/هل-تجوز-الخطبة-على-خطبة-الفاسق","audio":"https://files.zadapps.info/binbaz.org.sa/maram086 - 04 - .mp3","categories":["الخِطْبَة والاختيار "]},{"id":522,"question":"من خطب على خطبة أخيه ثم تزوجها هل يصح زواجه؟","title":"حكم زواج من خطب على خطبة أخيه","answer":"الجواب: الظاهر أنه يصح؛ لكن يكون عاصيًا.\n(دروس شرح بلوغ المرام، كتاب النكاح)","link":"https://binbaz.org.sa/fatwas/6352/حكم-زواج-من-خطب-على-خطبة-اخيه","audio":"https://files.zadapps.info/binbaz.org.sa/maram087 - 04 - .mp3","categories":["الخِطْبَة والاختيار "]},{"id":540,"question":"أب حج وخطب لابنه وهو غير محرم؟","title":"حكم خطبة الأب الحاج لابنه غير المُحْرِم","answer":"الجواب: الأقرب، والله أعلم، أنه لا بأس؛ لأن الزواج لغيره، ما هو له.\n(دروس شرح بلوغ المرام، كتاب النكاح)","link":"https://binbaz.org.sa/fatwas/6371/حكم-خطبة-الاب-الحاج-لابنه-غير-المحرم","audio":"https://files.zadapps.info/binbaz.org.sa/maram106 - 01 -  Start.mp3","categories":["الخِطْبَة والاختيار "]},{"id":995,"question":"نُخبركم أننا نُحبّكم في الله تعالى، ثم أما بعد: هل يجوز للشاب أن يتحدث مع خطيبته في الهاتف؟ وما حدود العلاقة بين الخاطب ومخطوبته؟ أفيدونا جزاكم الله خيرًا.","title":"ما حدود العلاقة بين الخاطب ومخطوبته؟","answer":"الجواب: أما المحبة في الله فنقول للسائل: أحبَّك الله الذي أحببتنا له، والتَّحاب في الله من أفضل القُربات، والواجب على المسلمين أن يتحابُّوا في الله، رجالًا ونساء، كما قال النبيُّ ﷺ: سبعة يُظلهم الله في ظلِّه يوم لا ظلَّ إلا ظله: إمام عادل، وشابٌّ نشأ في عبادة الله، ورجل قلبه مُعلَّقٌ بالمساجد –يعني: بالجماعة- ورجلان تحابَّا في الله، اجتمعا على ذلك، وتفرَّقا عليه جعلهم من السَّبعة الذين يُظلهم الله في ظلِّه، وهكذا النساء، مثَّل بالرجل والمراد النساء كذلك، فإذا تحابَّ النساءُ في الله، أو الرجل مع المرأة في الله، من دون شبهةٍ ولا فسادٍ، بل محبّة في الله فقط؛ دخلا في هذا الحديث.\nوالخامس: رجلٌ دعته امرأةٌ ذات منصبٍ وجمالٍ فقال: إني أخاف الله، ومثله المرأة دعاها ذو منصبٍ وجمالٍ فقالت: إني أخاف الله.\nوالسادس: رجل تصدَّق بصدقةٍ فأخفاها حتى لا تعلم شماله ما تُنفق يمينه، وهكذا المرأة إذا تصدَّقت بصدقةٍ فأخفتها حتى لا تعلم شمالها ما تُنفق يمينها، هذا تمثيلٌ بالرجل؛ لأنَّ جنس الرجل أفضل، وإلا فالمقصود العموم، يعمّ الرجال والنساء.\nالسابع: رجلٌ ذكر الله خاليًا ففاضت عيناه، رجلٌ ذكر الله يعني: ما عنده أحد، ففاضت عيناه بُكاءً من خشية الله جلَّ وعلا، وهكذا المرأة ذكرت الله خاليةً ففاضت عيناها، فالحكم واحد.\nوقال ﷺ: يقول الله يوم القيامة: أين المتحابُّون بجلالي؟ اليوم أُظلهم في ظلِّي يوم لا ظلَّ إلا ظلي، والأحاديث في هذا كثيرة.\nوأما الخطيب فله أن ينظر إلى خطيبته، وله أن يُكلمها فيما يتعلق بمصلحة النكاح، ولا شيء في ذلك، وقد أمر النبيُّ ﷺ الخاطبَ أن ينظر إلى خطيبته إلى ما يدعوه إلى نكاحها، وقال لبعض الأنصار: أنظرتَ إليها؟ قال: لا، قال: اذهب فانظر إليها، وقال في حديث المغيرة: فهو أقرب إلى أن يُؤدَم بينهما، لكن يكون نظره إليها بغير خلوةٍ، بحضرة أمها، أو أبيها، أو أخيها، أو غيرهم، من دون خلوةٍ، فلا بأس بذلك، ينظر إلى وجهها، إلى يدها، إلى قدمها، إلى شعرها، لا بأس، يُكلمها بالهاتف، يسألها عما يهمه من أمر دينها، من علمها، إلى غير ذلك مما يتعلق بالنكاح.\nولا يجوز أن يتواعد معها خلوة، أو يدعوها إلى فسادٍ قبل الزواج، كل هذا منكر، وإنما يسألها عمَّا يهمّ النكاح، وما يتعلق بالنكاح، أو تسأله كذلك فيما يتعلق بنكاحهما، وما يُسبب المحبَّة بينهما عند تمام النكاح، أما السؤال والمخاطبة بينهما في أمرٍ يُخشى منه الفساد، أو الخلوة، أو الاجتماع بها أو الذهاب بها إلى مكان كذا، ومكان كذا، أو التَّمشي بها؛ هذا منكرٌ لا يجوز.","link":"https://binbaz.org.sa/fatwas/21039/ما-حدود-العلاقة-بين-الخاطب-ومخطوبته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0836هل يجوز للشاب أن يتحدث مع خطيبته في الهاتف وما حدود العلاقة بين الخاطب ومخطوبته؟ ابن باز.mp3","categories":["الخِطْبَة والاختيار "]},{"id":1044,"question":"في أكثر جهات الجنوب يتزوج الرجلُ دون أن يرى مَن يتزوج من النساء، فما حكم الشرع في ذلك؟","title":"هل يجوز الزواج دون حصول الرؤية؟","answer":"الجواب: لا حرج في ذلك إذا تزوَّجها ولم يرها، لا حرج، لكن الأفضل أن يراها، فإن لم يتيسر يُرسل ثقةً من النساء تراها، أو يُرسل بعضَ محارمها ليراها ويُخبره، يستعين بالله ثم بمَن يرى من محارمها، أو بعض النساء يُرسلها إليها حتى تنظر، وإن تيسر النظر إليها فهو أفضل، النبي أمر بالنظر إليها عليه الصلاة والسلام، قال: إذا خطب أحدُكم امرأةً فاستطاع أن ينظر منها إلى ما يدعوه إلى النكاح فليفعل.\nوجاءه رجلٌ فقال: يا رسول الله، تزوجتُ امرأةً، قال: أنظرتَ إليها؟ قال: لا، قال: اذهب فانظر إليها، فالنظر فيه مصالح، وفي الحديث: إنَّ ذلك أقرب إلى أن يُؤْدَم بينهما، أو كما قال عليه الصلاة والسلام، يعني: أقرب إلى أن تحصل الأُلفة والمحبَّة بينهما، فإذا كان قد نظر إليها قبل ذلك ودخل على بصيرةٍ فهذا أوْلى وأفضل إذا تيسر.","link":"https://binbaz.org.sa/fatwas/21079/هل-يجوز-الزواج-دون-حصول-الروية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0875هل يجوز أن يتزوج الرجل دون أن يراها إلا عند الدخول بها؟ ابن باز فتاوى المحاضرات.mp3","categories":["الخِطْبَة والاختيار "]},{"id":1144,"question":"ما حكم دبلة الخطوبة لكلٍّ من الرجل والمرأة؟","title":"ما حكم دبلة الخطوبة للرجل والمرأة؟","answer":"الجواب:\nهذه لا أصلَ لها، ينبغي تركها، لا أصل لها، بل هذه من المحدثات التي أحدثها الناسُ وتلقوها عن الخارج، تركها هو الذي ينبغي.","link":"https://binbaz.org.sa/fatwas/21188/ما-حكم-دبلة-الخطوبة-للرجل-والمراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0984ما حكم دبلة الخطوبة للرجل والمراة؟.mp3","categories":["الخِطْبَة والاختيار ","البدع والمحدثات"]},{"id":1146,"question":"هل يجوز للمرأة أن تظهر للشخص الذي يرغب في خطبتها بكامل زينتها، أم أنَّ عليها أن تظهر في وجهها وكفّيها؟","title":"ما المشروع إظهاره من المخطوبة للخاطب؟","answer":"الجواب:\nنعم، نعم، الرسول ﷺ أمر بالنظر إليها، وحثّ على النظر إلى المخطوبة، فإذا ظهرت بزينتها فهذا أقرب إلى النجاح، كونها تظهر في ملابس حسنة، ولا بأس أن يرى شعورها ووجهها وكفَّيها وذراعيها ورجليها، كل هذا لا بأس به؛ لأنَّ هذا مما يدعو إلى النكاح، لكن لا يخلو بها، تكون من بعيدٍ، أو بحضرة أبيها، أو أخيها، أو أمها، لا يخلو بها.","link":"https://binbaz.org.sa/fatwas/21186/ما-المشروع-اظهاره-من-المخطوبة-للخاطب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0982هل يجوز للمرأة أن تظهر للشخص الذي يرغب لخطبتها بكامل زينتها أم فقط تظهر الوجة واليدين؟.mp3","categories":["الخِطْبَة والاختيار "]},{"id":2171,"question":"أحدهم يقول: إذا ألزمني والدي وقال: لا تدخل بيتي إذا ما خطبت الفلانية بنت فلان الفلانية؟","title":"حكم من يلزمه والده بخطبة فتاة معينة","answer":"الجواب:\nإن كانت ما تُناسبه فلا تلزمه طاعته: إنما الطاعة في المعروف، فلا تلزمه طاعته إلا في المعروف، إن كانت مناسبةً فينبغي له طاعة والده، وإن لم تكن مناسبة؛ لعدم جمالها، أو لسوء دينها؛ ما يلزمه طاعة والده، فالنكاح ليس سهلًا، وأمره عظيم.\nس: يقول: والدي سيطردني من البيت......؟\nج: إذا تزوجها من أجل والده جزاه الله خيرًا.\nس: يعني: يصبر؟\nج: نعم يصبر، لعل الله يجمع بينهما: فَعَسَى أَنْ تَكْرَهُوا شَيْئًا وَيَجْعَلَ اللَّهُ فِيهِ خَيْرًا كَثِيرًا [النساء:19]، فقد يتزوجها وهو كاره ثم يجمع الله بينهما.","link":"https://binbaz.org.sa/fatwas/22292/حكم-من-يلزمه-والده-بخطبة-فتاة-معينة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/طاعة الوالدين في أمر النكاح.mp3","categories":["الخِطْبَة والاختيار ","بر الوالدين"]},{"id":3641,"question":"إذا كانت المرأة مطلقة طلاقًا بائنًا فهل يُعرّض بخطبتها أم يصرّح في العدة؟","title":"حكم خطبة المطلقة طلاقًا بائنًا في العدة","answer":"الجواب: إذا كان الطلاق بائناً..... الأوْلى أن يكون تعريضا؛ لأنه ما هو وقت نكاح، هي ما زالت في العدة، ظاهر الأدلة العموم؛ لأنها لا تزال في وقت يحرم فيه النكاح.\nس: هل يقال بجواز النظر أو استحبابه؟\nالشيخ: مستحب، مستحب النظر إلى المخطوبة؛ لأن الرسول ﷺ أمر به.","link":"https://binbaz.org.sa/fatwas/23826/حكم-خطبة-المطلقة-طلاقا-باىنا-في-العدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/خطبة المرأة المطلقة طلاقًا بائنًا في العدة.mp3","categories":["الخِطْبَة والاختيار "]},{"id":3642,"question":"بعد نزول الحجاب: النظر قبل الخطبة أم بعدها؟","title":"متى يكون النظر للمخطوبة؟","answer":"الجواب: قبل الخطبة، ينظر أولًا فإن ناسبته خطب، وإلا ترك.","link":"https://binbaz.org.sa/fatwas/23828/متى-يكون-النظر-للمخطوبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/متى يكون النظر للمخطوبة.mp3","categories":["الخِطْبَة والاختيار "]},{"id":3643,"question":"هل يجوز النظر إلى الشعر؟","title":"هل يجوز النظر إلى شعر المخطوبة؟","answer":"الجواب: المشهور عند العلماء أن ينظر الوجه واليدين، وقال بعضهم: إلى ما يظهر منها غالبًا، ولا حرج لو رأى الشعر؛ لأن هذا يظهر منها غالبًا في بيتها ويرغّب فيها أيضًا، الشعر الجيد يرغّب فيها أيضًا، لا حرج على الصواب أن ينظر وجهها ويديها وقدميها وشعرها؛ لأن الشعر يظهر.","link":"https://binbaz.org.sa/fatwas/23829/هل-يجوز-النظر-الى-شعر-المخطوبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/النظر إلى المخطوبة.mp3","categories":["الخِطْبَة والاختيار "]},{"id":3656,"question":"لو خطب على خطبة أخيه فزوج فما حال العقد؟","title":"حكم زواج من خطب على خطبة أخيه","answer":"الجواب: الظاهر أنه يصح العقد لكن يأثم الخاطب؛ لأن النهي عن الخطبة ما هو عن النكاح.\nس: ولم لم يعلن المهر؟\nالشيخ: المهر بعدين، ولو ما سمي المهر يكون لها مهر المثل.","link":"https://binbaz.org.sa/fatwas/23844/حكم-زواج-من-خطب-على-خطبة-اخيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم زواج من خطب على خطبة أخيه.mp3","categories":["الخِطْبَة والاختيار "]},{"id":3659,"question":"خطبة النكاح هل هي واجبة؟","title":"هل خطبة النكاح مستحبة أم واجبة؟","answer":"الجواب: مستحبة، المعروف عند العلماء أنها مستحبة، ولهذا زوج النبي الواهبة ولم يخطب.\nس: ما يحتمل المناسبة أن الخطبة قبل العقد؟\nالشيخ: لا ما هو بظاهر، الظاهر أن المراد أن الزوج قد يسحر الناس، الخاطب قد يسحر الولي بكلامه؛ فينبغي التثبت والحذر.  أما خطبة الموعظة فهذه أمرها بسيط تقع بعد تمام الخطبة، وبعد الموافقة، ولا هي بلازمة.","link":"https://binbaz.org.sa/fatwas/23847/هل-خطبة-النكاح-مستحبة-ام-واجبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم خطبة النكاح.mp3","categories":["الخِطْبَة والاختيار "]},{"id":3973,"question":"بالنسبة للسلام على بنات العم أو بنات الخالة؟","title":"ما حكم السلام على بنات العم والخالة؟","answer":"الجواب: من الأقارب من الرحم التي توصل، لكن من دون مصافحة ومن دون تقبيل، بالكلام بس، مع الحجاب وعدم الخلوة.","link":"https://binbaz.org.sa/fatwas/24201/ما-حكم-السلام-على-بنات-العم-والخالة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم السلام على بنات العم أو بنات الخالة.mp3","categories":["الخِطْبَة والاختيار ","النظر والخلوة والاختلاط","قضايا المرأة","الآداب والأخلاق"]},{"id":5722,"question":"منذ زمن دعت وسائل الإعلام بأشكالها خارج البلاد الإسلامية إلى ظهور المرأة في ميدان الرجل للتقدم، ثم تلتها صحف بلدنا بالدعوة، فهل بقاء المرأة في حدودها الحالية يعتبر تخلفًا للأمة، وهل يدوم سكوت العلماء حتى تشتد نزعة المرأة إلى ما لا يحمد عقباه؟","title":"خطورة مخالطة المرأة للرجال","answer":"الجواب: وهذا من الداء الذي ينشره الأعداء، ويستغل الأعداء جهل الجاهلين، وجهل الكثير من الشباب، فينشرون بينهم هذه الدعوة إلى ظهور المرأة، وبروزها في ميدان العلم بين الرجال، وفي المدارس، وفي كل مكان مع الصبي جنبًا إلى جنب حتى تكثر الفاحشة، ويعم الفساد، وتنحدر الأخلاق إلى أخلاق سافلة، أخلاق بهيمية، هذه مقاصد أعداء الله. فالواجب هو بقاء المرأة على حالها الإسلامية، أن تكون في بيتها معلمة لأولادها، وأطفالها مصلحة لبيتها، معتنية بزوجها، وإذا كانت عندها فضل تنفع المسلمين في تعليم البنات في مدارس البنات، في الطب، والتمريض للنساء فيما يتعلق بالنساء، هذه حدودها، وبهذا يكون لها النجاة، ويكون لشعبها، ومجتمعها الخير والفوز والصلاح. أما إذا خالطت الشباب في مدارسهم، وفي مجتمعاتهم، وصرن كاتبات في المكاتب ... وتعمل جنبًا إلى جنب مع الرجل، صار ذلك الفساد، وصار الخراب، والدمار، ولا حول ولا قوة إلا بالله.","link":"https://binbaz.org.sa/fatwas/1026/خطورة-مخالطة-المراة-للرجال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_48.mp3","categories":["الخِطْبَة والاختيار ","النظر والخلوة والاختلاط","قضايا المرأة","الآداب والأخلاق"]},{"id":5735,"question":"خروجها مع السائق إلى المدرسة؟","title":"حكم خروج المرأة مع السائق","answer":"الجواب:  هذا خطر، نبهنا عليه غير مرة، مع السائق وغير السائق، مع أجنبي كونها تكون معه في غرفة، أو في حجرة يخلو بها ما يجوز، أو في السيارة مع السائق ما يجوز، بل لا بدّ أن يكون معها غيرها، أو السائق معه محرم، أو يكون معها امرأة، أو رجل آخر، حتى لا تصير خلوة، النبي ﷺ قال: لا يخلون رجل بامرأة فإن الشيطان ثالثهما نسأل الله السلامة.","link":"https://binbaz.org.sa/fatwas/1055/حكم-خروج-المراة-مع-الساىق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_72.mp3","categories":["الخِطْبَة والاختيار ","النظر والخلوة والاختلاط","قضايا المرأة","الآداب والأخلاق"]},{"id":5785,"question":"تقولون في قصة عبدالرحمن بن عوف: أنه عندما قال له أخوه: انظر إلى إحدى زوجاتي؛ فهل النظر بالنسبة للخاطب في المرأة حلال؟","title":"هل نظر الخاطب لمخطوبته جائز؟","answer":"الجواب:  نعم، النبي ﷺ أمر الخاطب أن ينظر، قال: إذا خطب أحدكم امرأة فإن استطاع أن ينظر إلى ما يدعوه إلى نكاحها فليفعل، فإن ذلك أقرب إلى أن يؤدم بينكما فالنظر إلى المخطوبة لا بأس به، من غير خلوة.  وجاءه رجل ذكر له أن زواج امرأة، أي أراد الزواج بها، أو عقد عليها، فقال: أنظرت إليها؟ قال: لا، قال: اذهب، فانظر إليها رواه مسلم في الصحيح، فهذا لا بأس به، بل هذا من أسباب الأدم بينهما، يعني: الجمع بينهما، واستقامة النكاح بينهما إذا تيسر ذلك، إذا سمح له أهله بذلك من غير خلوة، بل مع وجود محرمها، أو أمها، ونحو ذلك ممن حضوره ينافي الخلوة.  وقد ذكر جابر بن عبدالله الأنصاري  أنه خطب امرأة، فأراد أن ينظر إليها، قال: فجعلت أتتبع النخل، وهي في النخل في مزارع الأنصار، نخلة خلف نخلة يختبي لها وراء النخل، حتى رأى منها ما أعجبه، فخطبها.  فالمقصود: أنه إذا تيسر أن يراها بالإذن، والعلم فلا بأس، وإن لم يتيسر ذلك، ورآها من غير علمها، من فرجة، أو من وراء النخل، أو من كذا، أو من كذا من الطرق التي ليس فيها محذور في الشرع، وليس فيها خلوة فلا بأس. السؤال: الأهل يأثمون إذا لم يمكنوا الخاطب من الرؤية؟ الجواب: الظاهر لا يأثموا، ولكن الأولى، والأفضل أن يمكنوه؛ لأن هذا من أسباب الإدام بينهما، والجمع بينهما، والنبي أمر به -عليه الصلاة والسلام- قال: اذهب فانظر إليها فلما أمره أن ينظر؛ دل ذلك على أنه يستحب لهم أن يمكنوه، ما دام أمر به النبي فتمكين الرجل الذي أمره النبي أن ينظر تمكينه أولى. لكن بعض الناس من عاداتهم ألا يفعلوا، ويصعب عليهم ذلك، وبعضهم يقول: أخشى أن يراها فلا تعجبه، ثم يتحدث بين الناس، ثم ينفر الناس منها بعد ذلك، لهم تأويلات في هذا.","link":"https://binbaz.org.sa/fatwas/1120/هل-نظر-الخاطب-لمخطوبته-جاىز","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_127.mp3","categories":["الخِطْبَة والاختيار ","النظر والخلوة والاختلاط","قضايا المرأة","الآداب والأخلاق المحمودة"]},{"id":5923,"question":"......؟","title":"حكم جلوس الرجال والنساء في مجلس واحد للتحدث","answer":"الجواب: إذا كان النساء مع النساء، والرجال مع الرجال ما في كشف للرجال، ولا إظهار زينة؛ لا بأس. أما أن يجتمعوا جميعًا من غير تحجب، ومن غير مبالاة؛ فلا يجوز هذا، بل إذا كانت النساء مع النساء في وقت ما ليس فيه سهر، ولا إضاعة أوقات، ولا يجتمعن على باطل، لا بأس، إذا زار النساء الجيران، هذا طيب بين الجيران، لكن بشرط أن يكون ذلك على غير سوء، على غير عمل صالح، يعني حتى لا يكون هذا على عمل سيئ، ولا يكون معه التكشف للجار، أو لزوج الجارة، أو ما أشبه ذلك، بل يكون معه احتشام، وتستر، وحجاب، والنساء مع النساء، والرجال مع الرجال في غير معصية، بل زيارات مناسبة في حد مناسب، وفي اجتماع مناسب للتنفيس عن النفس، والترويح عنها، وللتحدث الذي جرت به العادة بين الجيران، فهذا لا بأس به.","link":"https://binbaz.org.sa/fatwas/1268/حكم-جلوس-الرجال-والنساء-في-مجلس-واحد-للتحدث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_255.mp3","categories":["الخِطْبَة والاختيار ","النظر والخلوة والاختلاط","قضايا المرأة","الآداب والأخلاق"]},{"id":6169,"question":"إذا طلب الزوج مقابلة المرأة دون خلوة، فما هو الدليل على ذلك، والرسول ﷺ يقول: كل المرأة عورة؟","title":"حكم النظر إلى المخطوبة وضوابط ذلك","answer":"الجواب: لا حرج فيها، المرأة عورة، مثل ما جاء في الحديث، لكن استثنى النبي ﷺ من ذلك ما يتعلق بالخاطب إذا خطب، وأحب أن ينظر فلا بأس، النبي ﷺ قال: إذا خطب أحدكم المرأة فإن استطاع أن ينظر منها ما يدعوه إلى نكاحها فليفعل إذا استطاع أن ينظر، ولو من بعد من غير علمها، فلا بأس، خطب جابر بن عبدالله الأنصاري  امرأة من الأنصار ولم يرها قال: فجعلت أتتبع النخل لعلي أراها حتى رأى منها ما أعجبه منها فتزوجها. فالمقصود: أنه إذا تيسر له أن يراها ولو من بعيد، ولو من طريق وجوده في بيت أهلها، فتمر وهم راضون بذلك، وما أشبه ذلك، وإذا تيسر أن أباها، أو أخاها يحضرونه عندهم، ويدخلونها عليه، ويراها بغير خلوة بحضرة أبيها، أو أخيها، أو أمها، أو نحو ذلك فلا بأس، هذا أذن فيه النبي ﷺ ورخص.","link":"https://binbaz.org.sa/fatwas/1628/حكم-النظر-الى-المخطوبة-وضوابط-ذلك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_519.mp3","categories":["الخِطْبَة والاختيار ","النظر والخلوة والاختلاط","قضايا المرأة","الآداب والأخلاق"]},{"id":6177,"question":"إذا طلب الزوج مقابلة المرأة دون خلوة، فما هو الدليل على ذلك، والرسول ﷺ يقول: كل المرأة عورة؟","title":"حكم النظر إلى المخطوبة وضوابط ذلك","answer":"الجواب: لا حرج فيها، المرأة عورة، مثل ما جاء في الحديث، لكن استثنى النبي ﷺ من ذلك ما يتعلق بالخاطب إذا خطب، وأحب أن ينظر فلا بأس، النبي ﷺ قال: إذا خطب أحدكم المرأة فإن استطاع أن ينظر منها ما يدعوه إلى نكاحها فليفعل إذا استطاع أن ينظر، ولو من بعد من غير علمها، فلا بأس، خطب جابر بن عبدالله الأنصاري  امرأة من الأنصار ولم يرها قال: فجعلت أتتبع النخل لعلي أراها حتى رأى منها ما أعجبه منها فتزوجها. فالمقصود: أنه إذا تيسر له أن يراها ولو من بعيد، ولو من طريق وجوده في بيت أهلها، فتمر وهم راضون بذلك، وما أشبه ذلك، وإذا تيسر أن أباها، أو أخاها يحضرونه عندهم، ويدخلونها عليه، ويراها بغير خلوة بحضرة أبيها، أو أخيها، أو أمها، أو نحو ذلك فلا بأس، هذا أذن فيه النبي ﷺ ورخص.","link":"https://binbaz.org.sa/fatwas/1628/حكم-النظر-الى-المخطوبة-وضوابط-ذلك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_519.mp3","categories":["الخِطْبَة والاختيار ","النظر والخلوة والاختلاط","قضايا المرأة","الآداب والأخلاق"]},{"id":6218,"question":"ما قول سماحتكم فيمن سأل عن الإسبال، فقال: هو الكبر، هل هذا يعتبر تفسير، أو تغيير لكلام رسول الله؟ وما حكمه؟","title":"الإسبال وسيلة للكبر","answer":"الجواب: الإسبال وسيلة إلى الكبر، وليس هو الكبر، لكن في الغالب أنه وسيلة، والغالب أنه يدعو إلى الكبر، وأما أنه هو الكبر بعينه لا، لكنه وسيلة إلى الكبر، وذريعة إليه، ولهذا حرمه الإسلام، ونهى عنه؛ لأنه وسيلة إلى الكبر، وهو وسيلة إلى إفساد الثياب، وتنجيسها، وتوسيخها، وإعدامها، ولما رأى عمر  شابًا يمس ثوبه الأرض، قال له: يا عبدالله، ارفع ثوبك؛ فإنه أتقى لربك، وأنقى لثوبك.","link":"https://binbaz.org.sa/fatwas/1707/الاسبال-وسيلة-للكبر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_564.mp3","categories":["الأخلاق المذمومة","اللباس والزينة","الخِطْبَة والاختيار "]},{"id":6244,"question":"إذا حضرت أنا وزوجتي، وأخي، وزوجته في مجلس واحد فهل هذا جائز؟","title":"حكم اجتماع الأخوين مع زوجتيهما في مجلس واحد","answer":"الجواب: لا بأس أن تجتمع العائلة في مجلس واحد، لكن مع الحجاب، والتستر، والبعد عما حرم الله، والمرأة زوجة أخيك عندكم، أو زوجة خالك، أو زوجة عمك، أو ما أشبه ذلك عندكم في المجلس، أو في البيت، فهذا لا محذور فيه، هذا من عهد النبي إلى يومنا هذا، الناس يتزاورون، ويزور بعضهم بعضًا، ويلتقي بعضهم بعضًا، ويزور الأجنبي بلاد أصدقائه، وبيت أصدقائه، ولو كان غير أخ، ويكون نساؤه مع نسائهم، وربما اجتمعوا جميعًا، لكن مع الحجاب، والستر، والبعد عن الكلمات الخبيثة النابية، هذا كله لا حرج فيه. السؤال: وإذا لم يكن هناك حجاب؟ الجواب: ما يجوز يجب عليها أن تستر، وإلا تبتعد، لا تجلس معهم، وإذا كانت لا بدّ من جلوسها فيقم هو الذي ليس محرمًا لها، أو يغض بصره، ويعرض عنها؛ حتى يكون امتثل أمر الله.","link":"https://binbaz.org.sa/fatwas/1736/حكم-اجتماع-الاخوين-مع-زوجتيهما-في-مجلس-واحد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_579.mp3","categories":["الخِطْبَة والاختيار ","النظر والخلوة والاختلاط","قضايا المرأة","الآداب والأخلاق المحمودة"]},{"id":6377,"question":"ما هو النمص؟ وما حكمه؟ وأين يتم في جسم الإنسان؟ وهل يشمل الرجال، والنساء؟","title":"حكم النمص","answer":"الجواب: النمص هو أخذ شعر الحاجبين، وألحق به بعض أهل العلم شعر الوجه المعتاد، فلا يجوز نمصه، النبي ﷺ لعن النامصة، والمتنمصة، قال أهل العلم: النمص أخذ شعر الحاجبين بالمنماص، وهو المنقاش، تزين شعر حاجبيها بالمناقيش حتى تأخذ بعض الشعرات، فإذا كان بالمنقاش يحرم، فكيف بأكثر من المنقاش؟!  السؤال: كذلك شعر اليدين، والرجلين؟ الجواب: اليدين، والرجلين ما ورد فيها شيء، ما نعلم فيها شيئًا.","link":"https://binbaz.org.sa/fatwas/1955/حكم-النمص","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_742.mp3","categories":["الأخلاق المذمومة","اللباس والزينة","الخِطْبَة والاختيار "]},{"id":6387,"question":"ما هو النمص؟ وما حكمه؟ وأين يتم في جسم الإنسان؟ وهل يشمل الرجال، والنساء؟","title":"حكم النمص","answer":"الجواب: النمص هو أخذ شعر الحاجبين، وألحق به بعض أهل العلم شعر الوجه المعتاد، فلا يجوز نمصه، النبي ﷺ لعن النامصة، والمتنمصة، قال أهل العلم: النمص أخذ شعر الحاجبين بالمنماص، وهو المنقاش، تزين شعر حاجبيها بالمناقيش حتى تأخذ بعض الشعرات، فإذا كان بالمنقاش يحرم، فكيف بأكثر من المنقاش؟!  السؤال: كذلك شعر اليدين، والرجلين؟ الجواب: اليدين، والرجلين ما ورد فيها شيء، ما نعلم فيها شيئًا.","link":"https://binbaz.org.sa/fatwas/1955/حكم-النمص","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_742.mp3","categories":["الأخلاق المذمومة","اللباس والزينة","الخِطْبَة والاختيار "]},{"id":6458,"question":"خطبت بنتًا تصلي، وتصوم، وتحافظ على الفروض، ولكن أمي لا تريدها زوجة لي؛ لخلاف بين أهلها، ومصممة على ذلك، فهل أطيع أمي، أم ماذا أفعل؟","title":"حكم من خطب بنتا ذات دين مع كون الأم ترفضها","answer":"الجواب: لا تعجل في طاعة أمك من الطاعة في المعروف، الطاعة في المعروف، لا في المعاصي، فالزوجة مهمة، فإذا كانت جيدة في دينها، ومستقيمة؛ فعليك أن تتكلم مع الوالدة بأسلوب حسن، والعبارات الطيبة؛ حتى ترضى -إن شاء الله- وعليك أن تقوم مع الزوجة بالنصيحة أيضًا حتى تقدم الأخلاق الفاضلة، والسيرة الحميدة لأمك، وحتى لا يقع التباغض بينها وبين أهلك. فالمقصود: أنك على ثغر من ثغور الإسلام، فعليك أن تعتني، ترضي أمك، وترضي من حولك بالكلام الطيب، والأسلوب الحسن، وتنصح للزوجة بأن تستعمل معهم اللين، والكلام الطيب؛ حتى يكون -إن شاء الله- بعد ذلك الاجتماع، والوئام، وحتى لا تحتاج إلى الطلاق.","link":"https://binbaz.org.sa/fatwas/2189/حكم-من-خطب-بنتا-ذات-دين-مع-كون-الام-ترفضها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_814.mp3","categories":["الخِطْبَة والاختيار ","بر الوالدين"]},{"id":6480,"question":"من عادات بعض البلاد الإسلامية أن يقدم الرجل لعروسه شبكة عند الزواج منها، ومنها خاتم، أحدهما من الرجل، والثاني للمرأة، وينقش على الخاتم اسمها، فهل هذا تشبه باليهود؟","title":"حكم نقش اسم المرأة على الخاتم الدبلة في الأعراس","answer":"الجواب: لا ينبغي للمؤمن أن يتشبه بأعداء الله، لا ينبغي لأهل الإيمان أن يتشبهوا بأعداء الله، فما كان من عادة أعداء الله لا ينبغي لأهل الإيمان أن يتشبهوا به، لا في الخاتم، ولا في غيره.  ولا يجوز للرجل أن يلبس الخاتم الذي هو يسمونه الدبلة من الذهب؛ لأن الذهب حرام على الرجال، خواتيم الذهب محرمة على الرجال، الرسول ﷺ نهى عن خواتيم الذهب، ولما رأى رجلًا في يده خاتمًا من ذهب؛ نزعه، وطرحه -عليه الصلاة والسلام- وقال: يعمد أحدكم إلى جمرة من نار، فيضعها في يده فهذا يدل على تحريم خواتم الذهب، وأنها من الكبائر؛ لأن فيها الوعيد بالنار، ولا ينبغي التشبه بأعداء الله، لا في الأعراس، ولا في غيرها، ولا ينبغي أن يكتب اسم المرأة في خاتمه، بل يكتب اسمه هو، لا يكتب اسم امرأته في خاتمه، هذا تشبه بأعداء الله، لا يجوز، وهذا نزول، وضعف، وتقصير، لا حول ولا قوة إلا بالله.","link":"https://binbaz.org.sa/fatwas/2237/حكم-نقش-اسم-المراة-على-الخاتم-الدبلة-في-الاعراس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_857.mp3","categories":["اللباس والزينة","الخِطْبَة والاختيار ","البدع والمحدثات"]},{"id":6495,"question":"من عادات بعض البلاد الإسلامية أن يقدم الرجل لعروسه شبكة عند الزواج منها، ومنها خاتم، أحدهما من الرجل، والثاني للمرأة، وينقش على الخاتم اسمها، فهل هذا تشبه باليهود؟","title":"حكم نقش اسم المرأة على الخاتم الدبلة في الأعراس","answer":"الجواب: لا ينبغي للمؤمن أن يتشبه بأعداء الله، لا ينبغي لأهل الإيمان أن يتشبهوا بأعداء الله، فما كان من عادة أعداء الله لا ينبغي لأهل الإيمان أن يتشبهوا به، لا في الخاتم، ولا في غيره.  ولا يجوز للرجل أن يلبس الخاتم الذي هو يسمونه الدبلة من الذهب؛ لأن الذهب حرام على الرجال، خواتيم الذهب محرمة على الرجال، الرسول ﷺ نهى عن خواتيم الذهب، ولما رأى رجلًا في يده خاتمًا من ذهب؛ نزعه، وطرحه -عليه الصلاة والسلام- وقال: يعمد أحدكم إلى جمرة من نار، فيضعها في يده فهذا يدل على تحريم خواتم الذهب، وأنها من الكبائر؛ لأن فيها الوعيد بالنار، ولا ينبغي التشبه بأعداء الله، لا في الأعراس، ولا في غيرها، ولا ينبغي أن يكتب اسم المرأة في خاتمه، بل يكتب اسمه هو، لا يكتب اسم امرأته في خاتمه، هذا تشبه بأعداء الله، لا يجوز، وهذا نزول، وضعف، وتقصير، لا حول ولا قوة إلا بالله.","link":"https://binbaz.org.sa/fatwas/2237/حكم-نقش-اسم-المراة-على-الخاتم-الدبلة-في-الاعراس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_857.mp3","categories":["اللباس والزينة","الخِطْبَة والاختيار ","البدع والمحدثات"]},{"id":6504,"question":"ابتلينا في بلادنا بالمدارس المختلطة بين البنين والبنات، فتيان وفتيات، وأنا شاب متدين والحمد لله، وعينت مدرسًا بإحدى هذه المدارس المختلطة، حيث لا يوجد مدرس للبنين فقط في بلدنا، ولكن توجد مدرسة بعيدة عن بلدي، تحتاج لمجهود شاق طوال اليوم، ومصاريف كثيرة، وراتبي صغير وقليل، فهل أبقى في المدرسة المختلطة، أم أطلب النقل إلى المدرسة الأخرى، ولو دفعت مالًا للقائمين؟","title":"حكم التدريس في المدارس المختلطة","answer":"الجواب: انظر ما هو أصلح لقلبك، إذا كان تخشى على نفسك؛ فانتقل عنها، وإذا كنت ترى أن وجودك فيه صلاح للمدرسة، وحثهم على طاعة الله، وتحث البنات على الستر، وتغض بصرك، وتعمل ما ينفع الأمة تفعل.  اعمل ما هو الأصلح إن كنت تخشى على نفسك من وجود البنات، فاتق الله، واحذر، وانتقل عن هذه المدرسة، إلى مدارس أخرى، أو إلى عمل آخر، وإن كنت ترى أن وجودك في المدرسة فيه مصلحة للمسلمين، ونفع للمسلمين، وتستطيع أن تغض بصرك، وأن تأمرهن بالحجاب، والتستر، وتجتهد مع إخوانك الباقين في هذا الأمر، فأنت على ثغر عظيم من ثغور الإسلام، فاتق الله في ذلك، واعمل ما تستطيع من الخير، وإلا فانتقل.","link":"https://binbaz.org.sa/fatwas/2261/حكم-التدريس-في-المدارس-المختلطة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_884.mp3","categories":["الخِطْبَة والاختيار ","النظر والخلوة والاختلاط","قضايا المرأة","الآداب والأخلاق المحمودة"]},{"id":6507,"question":"هل يجوز مراسلة الخطيب لخطيبته قبل أن يعقد عليها؟ وهل الخطبة مشروعة؟","title":"حكم مراسلة الخاطب لخطيبته قبل العقد","answer":"الجواب: لا بأس كأن يراسلها بشيء ينفعها، هدية، أو غير ذلك، لا بأس إذا كان تم الخطبة بينهما، أو أراد أن يرغبهما في ذلك؛ أرسل إلى أهلها، وإليها بهدايا يرجوهم أن يوافقوا على الزواج؛ لا بأس بذلك، المهم أن يكون ذلك عن طريق شرعية، لا عن طريق خلوة، ولا عن طريق مقابلة خبيثة، ولكن عن طريق التودد إلى أهلها، وإليها بالهدايا حتى يستجيب لرغبته؛ لا بأس بذلك.","link":"https://binbaz.org.sa/fatwas/2268/حكم-مراسلة-الخاطب-لخطيبته-قبل-العقد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_891.mp3","categories":["الخِطْبَة والاختيار ","النظر والخلوة والاختلاط","قضايا المرأة","الآداب والأخلاق المحمودة"]},{"id":6526,"question":"ابتلينا في بلادنا بالمدارس المختلطة بين البنين والبنات، فتيان وفتيات، وأنا شاب متدين والحمد لله، وعينت مدرسًا بإحدى هذه المدارس المختلطة، حيث لا يوجد مدرس للبنين فقط في بلدنا، ولكن توجد مدرسة بعيدة عن بلدي، تحتاج لمجهود شاق طوال اليوم، ومصاريف كثيرة، وراتبي صغير وقليل، فهل أبقى في المدرسة المختلطة، أم أطلب النقل إلى المدرسة الأخرى، ولو دفعت مالًا للقائمين؟","title":"حكم التدريس في المدارس المختلطة","answer":"الجواب: انظر ما هو أصلح لقلبك، إذا كان تخشى على نفسك؛ فانتقل عنها، وإذا كنت ترى أن وجودك فيه صلاح للمدرسة، وحثهم على طاعة الله، وتحث البنات على الستر، وتغض بصرك، وتعمل ما ينفع الأمة تفعل.  اعمل ما هو الأصلح إن كنت تخشى على نفسك من وجود البنات، فاتق الله، واحذر، وانتقل عن هذه المدرسة، إلى مدارس أخرى، أو إلى عمل آخر، وإن كنت ترى أن وجودك في المدرسة فيه مصلحة للمسلمين، ونفع للمسلمين، وتستطيع أن تغض بصرك، وأن تأمرهن بالحجاب، والتستر، وتجتهد مع إخوانك الباقين في هذا الأمر، فأنت على ثغر عظيم من ثغور الإسلام، فاتق الله في ذلك، واعمل ما تستطيع من الخير، وإلا فانتقل.","link":"https://binbaz.org.sa/fatwas/2261/حكم-التدريس-في-المدارس-المختلطة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_884.mp3","categories":["الخِطْبَة والاختيار ","النظر والخلوة والاختلاط","قضايا المرأة","الآداب والأخلاق المحمودة"]},{"id":6592,"question":"فأنا شاب وولي أمر فتاة -إن شاء الله- أنها صالحة، ومشكلتي: أن هذه الفتاة أختي، ولكن تقدم لخطبتها شاب صالح، ويحفظ القرآن، وأعرفه بحسن الخلق، وهي تريد هذا الشاب، بل أخبرتني أنها تحبه في الله، لكن هذا الشاب من عائلة أقل من عائلتنا في النسب، ماذا أعمل؟ فإن أختي تقول: لن أتزوج غيره، وأبناء عمها يهددون، ويقولون: لا تزوجوها، ماذا أعمل؟ وما الطريق، هل أزوجها هذا الشاب الصالح، وأدفع أبناء عمها؟","title":"حكم تزويج الولي موليته لرجل صالح لكنه دونها في النسب","answer":"الجواب: الواجب على الأولياء أن ينظروا لمولاتهم من هو أصلح لها في دينها ودنياها، ولو كان من غير قبيلتهم، بل عليهم أن ينظروا الأصلح، ولو كان من أي قبيلة، إذا صلح دينه، واستقام أمره، فإذا لم يستقيموا على ذلك، ووجدوا لها من هو يناسبها؛ فعليها أن تجتهد في موافقتهم إذا كان مستقيمًا أيضًا، ولا بأس به، وإن تنازلت عن بعض هواها؛ لمراعاة أقاربها، وأوليائها، ولسد باب الشر، والقضاء على أسباب الفرقة، والاختلاف؛ فإن تنازلها عن بعض الشيء ما دام المتنازل له لا بأس به في دينه، وإن كان دون ما أرادت في نفسها، لكنه في نفسه طيب، وفي نفسه صالح في دينه، وهو من قبيلتها، أو من قبيلة يرضاها أولياؤها؛ فهذا أولى من النزاع في الشقاق. فإذا اشتد الأمور فلم تتنازل هي، ولم يتنازل هم، رجع الأمر إلى المحكمة، وفي المحكمة الكفاية -إن شاء الله- تنظر في الأمر، وعندها الشرع المطهر، كافي في كل شيء، سبحان الذي أنزله، لكن إذا تنازل الأولياء، والتمسوا لها من هو أصلح، وتركوا تعصبهم لواحد معين، ولو كان ابن عم قريب، ما هو بلازم ابن عمه القريب، ولا هو بلازم من قبيلتها، العرب كلهم بعضهم لبعض أكفاء، وأهل الدين أكفاء، وإن كانوا ليسوا من العرب، لو زوجوها مولًى، أو عتيقًا من العتقاء، أو أعجميًا من العجم؛ فلا بأس، يقول الله -جل وعلا-: إِنَّ أَكْرَمَكُمْ عِنْدَ اللَّهِ أَتْقَاكُمْ [الحجرات:13]. ليس شرطًا أن القحطانية ما تأخذ إلا قحطاني، والسبيعية ما تأخذ إلا سبيعي، والهاشمية ما تأخذ إلا هاشمي، ليس من شرط هذا، النبي ﷺ زوج زينب بنت جحش أسدية أمها عمة النبي ﷺ من بني هاشم، زوجها مولًى عتيقًا زيد بن حارثة، عتيق مولى، وزوج فاطمة بنت قيس قرشية من قريش، زوجها ابنه أسامة بن زيد، وهو مولى عتيق أيضًا، وبلال تزوج من زهرية من بني زهرة من قريشن وهو عتيق من الحبشة. فالمقصود: أن هذه الأمور انطلت على كثير من الناس في العرب، وآثروها على الحق والهدى؛ فغلطوا في ذلك، فالواجب على الأولياء أن يعنوا بالأمر الشرعي، وأن يجاهدوا الشر في ذلك، فإذا غلبت .. وخافوا من شر بينهم؛ فيلتمسوا لها من يناسبها، ولو من قبيلة أخرى، لا يلزموها بشيء ما ترضاه، ما هو بلزوم بابن عمها، لا يجوز يجبروها على ابن عمها أبدًا، ولا ابن خالها، يلتمس لها من بقية القبائل، والناس الآخرين من العرب، وإن كانوا بعيدين إذا لم يرضوا بتزويجها من غير العرب، يلتمس لها من العرب، وإن زوجوها من غير العرب، من الأعاجم، من الموالي من ذوي الدين، والتقوى؛ فلا بأس، ولا حرج، والحمد لله. قد سبقهم في هذا الأخيار من هذه الأمة، وسبقهم إلى هذا الرسول ﷺ وأصحابه، فالأمر في هذا واسع يقول الله : يَا أَيُّهَا النَّاسُ إِنَّا خَلَقْنَاكُمْ مِنْ ذَكَرٍ وَأُنْثَى وَجَعَلْنَاكُمْ شُعُوبًا وَقَبَائِلَ لِتَعَارَفُوا [الحجرات:13]، ثم قال بعدها إِنَّ أَكْرَمَكُمْ عِنْدَ اللَّهِ أَتْقَاكُمْ إِنَّ اللَّهَ عَلِيمٌ خَبِيرٌ [الحجرات:13] ما قال: إن أكرمكم عند الله بنو هاشم، أو قريش، أو بنو تميم، أو بنو فلان لا، إِنَّ أَكْرَمَكُمْ عِنْدَ اللَّهِ أَتْقَاكُمْ[الحجرات:13] أتقاكم وإن كان أعجميًا، وإن كان مولى قد أعتقه فلان، أو فلان، هو الأكرم عند الله، وإن كان الذي ليس بتقي قرشيًا هاشميًا فلا قيمة له عند الله، هذا أبو لهب قرشي هاشمي من أهل النار، وأبو طالب كذلك، وأبو جهل كذلك، كلهم قرشيون، ومع ذلك صاروا إلى النار لأعمالهم الخبيثة. ثم أمر آخر: وهو أن التعصب بين القبيلة لفلان، أو فلان، يضرون به بنتهم، ويضرون به مولاتهم، هذا ظلم لا يجوز لهم، بل إذا كرهته البنت لا يحجرون عليها، ولا يعطلونها، بدل ابن عمها غيره العرب كثيرون، وغير العرب كثيرين، فإذا خطبها كفء، ولو من غير قبيلتهم، ولو من غير بني عمهم؛زوجوا، العرب كثيرون، وإذا أبوا أن يزوجوا مولى، أو عبدًا منهم يزوجوا من العرب، العرب كثيرون يلتمسوا لها الأخ الطيب، وإذا خطبها الطيب في نفسه، وفي دينه، ولو كان بعيدًا منهم؛ فليزوجوه والحمد لله، ولا يجبرونها على من لا ترضاه من ابن عم، أو ابن خال، أو شيخ كبير لا ترضاه، وهي شابة. الواجب: أن يراعى أمرها، وأن تراعى رغبتها، لا في الفاسدين، لكن في الصالحين، أما أنها تجبر لأجل شهوة وليها؛ لأن وليها هذا نسيبه آخذ بنته، أو آخذ أخته، يجبروها على والد نسيبه، أو أخت نسيبه، أو أخو زوجته .. هذا غلط، هذا ظلم، أو يجبروها على شيخ كبير؛ لأنه يزوجه بنته، أو يزوجه بنته شغارًا، زوجني، وأزوجك، يجبر بنته حتى الذي يزوجه يزوجه بنته، أو أخته، هذا ظلم أيضًا، النبي نهى عن الشغار، وحذر من الشغار -عليه الصلاة والسلام- ولا يجوز أنه يزوج شغارًا يقول: أعطني بنتك، وأعطك بنتي، أعطني أختك، وأعطك أختي، أو أعطني ولدك، وتعطي ولدي، هذا منكر، لا يجوز هذا، ولا يحل.  الواجب على المؤمنين أن يتباعدوا عن هذا الشيء، وأن يزوجوه من غير إجبار للبنات، ولو كانت بنتك لا تجبرها، زوجها من ترضى من الأخيار الطيبين، وليس لك أن تجبرها إذا أبت لا تزوجها حتى يأتيها من ترضاه من المسلمين، ولو جلست إلى أن تشيب، لا يضرك ذلك مادام لم تجبرها فأنت في سلامة، أما أن تجبرها، وتضرها، فلا يجوز لك أبدًا، الحاجة لها.","link":"https://binbaz.org.sa/fatwas/2435/حكم-تزويج-الولي-موليته-لرجل-صالح-لكنه-دونها-في-النسب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_962.mp3","categories":["الخِطْبَة والاختيار ","بر الوالدين"]},{"id":6625,"question":"هل يجوز للأخ المسلم عند خطبته لفتاة مسلمة أن يجلس معها ليعلمها القرآن، ويتعرف على أخلاقها قبل العقد بها، والارتباط بها ؟","title":"حكم مجالسة المخطوبة للتعرف على أخلاقها","answer":"الجواب: له أن ينظر إليها فقط، أما يجلس معها، ويخلو بها ليس له ذلك، لا للقرآن، ولا لغيره، لكن ينظر إليها بحضرة أبيها، أو أخيها، أو غيرهم، لا يخلو بها، وينظر إليها؛ لعل الله يأدم بينهما؛ لعلها توافقه، ثم بعد هذا يعقد عليها إذا ناسبته، أما أنه يخلو بها، أو يجلس معها للتعليم، فالشيطان لا يؤمن أن ينزغ بينهما. السؤال: مرة، أو مرات؟ الجواب: النظرة الواحدة الكافية، وإذا مكثت ما رآها النظر الكافي، لا بأس أن ينظر مرة أخرى؛ ليتحقق عنها ما يريد.","link":"https://binbaz.org.sa/fatwas/2482/حكم-مجالسة-المخطوبة-للتعرف-على-اخلاقها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_5739.mp3","categories":["الخِطْبَة والاختيار ","النظر والخلوة والاختلاط","قضايا المرأة","الآداب والأخلاق"]},{"id":6640,"question":"هل يجوز للأخ المسلم عند خطبته لفتاة مسلمة أن يجلس معها ليعلمها القرآن، ويتعرف على أخلاقها قبل العقد بها، والارتباط بها ؟","title":"حكم مجالسة المخطوبة للتعرف على أخلاقها","answer":"الجواب: له أن ينظر إليها فقط، أما يجلس معها، ويخلو بها ليس له ذلك، لا للقرآن، ولا لغيره، لكن ينظر إليها بحضرة أبيها، أو أخيها، أو غيرهم، لا يخلو بها، وينظر إليها؛ لعل الله يأدم بينهما؛ لعلها توافقه، ثم بعد هذا يعقد عليها إذا ناسبته، أما أنه يخلو بها، أو يجلس معها للتعليم، فالشيطان لا يؤمن أن ينزغ بينهما. السؤال: مرة، أو مرات؟ الجواب: النظرة الواحدة الكافية، وإذا مكثت ما رآها النظر الكافي، لا بأس أن ينظر مرة أخرى؛ ليتحقق عنها ما يريد.","link":"https://binbaz.org.sa/fatwas/2482/حكم-مجالسة-المخطوبة-للتعرف-على-اخلاقها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_5739.mp3","categories":["الخِطْبَة والاختيار ","النظر والخلوة والاختلاط","قضايا المرأة","الآداب والأخلاق"]},{"id":7120,"question":"نرجو نصح سماحتكم فيما يحصل من مدينة جيزان أنه إذا حصل عندهم مناسبة زواج، أو ختان؛ يدخلون الرجال يطبلون، ويسمونهم مزلفين، ويطبلون هؤلاء في وسط النساء، والنساء ينثرن عليهم النقود، وهم يرقصون بدون حياء من الله؟","title":"حكم دخول الرجال بين النساء في مناسبات الزواج","answer":"الجواب:\n\nهذا قد بُيِّنَ لهم، وكتب لهم في هذا، والدعاة الذين هناك مكلفون بهذا الشيء، ببيان هذا الشيء، ونسأل الله أن يهدي الجميع. \n\nكثير من الناس قد يسمع النصيحة ولا يلتفت إليها، ويرى أن العادة التي اعتادها شيئًا لازمًا، يقدمها على ما قاله الله ورسوله، وهل عودي الرسل والمصلحون إلا بالعوائد الضارة، العوائد المخالفة للشرع، عوائد الجاهلية هي التي عودي بها الرسل، وعودي بها المصلحون. \n\nفالواجب على المسلم أن يبتعد عن العادة السيئة المخالفة للشرع، وألا يغتر بما عليه أسلافه إذا كان شيئًا باطلًا، فالعوائد لا يحتج بها، بل تعرض على الأدلة الشرعية، فإن جادت؛ أخذ بها، وإلا وجب طرحها وإن كانت عادة للآباء والأسلاف.\n\nولا ينبغي للعاقل أن يكون مثل ما قال الجاهلون من الكفار: إِنَّا وَجَدْنَا آبَاءَنَا عَلَى أُمَّةٍ وَإِنَّا عَلَى آثَارِهِمْ مُقْتَدُونَ [الزخرف:23] هذه حجة الكفرة التي احتجوا بها على الرسل إِنَّا وَجَدْنَا آبَاءَنَا عَلَى أُمَّةٍ وَإِنَّا عَلَى آثَارِهِمْ مُقْتَدُونَ [الزخرف:23] هذه حجة داحضة باطلة، ما يجوز لأي مسلم أن يحتج بها، بل يجب أن يعرض ما أشكل عليه على الأدلة الشرعية، ويسأل أهل العلم بالشرع عن ذلك، ولا يقول هذه عادة أبي، أو جدي، أو أهل بلدي، ويكتفي بها، ولو خالفت الشرع.\n\nالسؤال: العامة قلت تكتبون لهم، وأنا في روحة أهلي وجدتهم لا زالوا على حالتهم وأشد؟\n\nالجواب: ولو، الرسائل جاءتهم عدة رسائل في هذا، وقرأها عليهم الدعاة، ولكن العادات مثل ما قيل قاهرات، قل من يتركها، نسأل السلامة، نسأل الله أن يهدينا وإياهم.","link":"https://binbaz.org.sa/fatwas/3168/حكم-دخول-الرجال-بين-النساء-في-مناسبات-الزواج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1526.mp3","categories":["الخِطْبَة والاختيار ","النظر والخلوة والاختلاط","قضايا المرأة","الآداب والأخلاق"]},{"id":7142,"question":"فضيلة شيخي! جنوب المملكة يستبيحون كشف الوجه لأخي الزوج وأقاربه، فما هو الرد على هؤلاء مع أمرها بذلك؟","title":"حكم كشف الوجه لأخي الزوج وأقاربه","answer":"الجواب:\n\nهذا في الجنوب وفي غير الجنوب، الرسول ﷺ قال: إياكم والدخول على النساء قيل: يا رسول الله أرأيت الحمو؟ قال: الحمو الموت الحمو: أخو الرجل، وعم الرجل.\n\nفإذا تساهلت في الكشف له هذا من وسائل الشر، إذا تساهلت؛ دل على ضعف إيمانها، ودعاه ذلك إلى الطمع فيها، فلا يجوز لها أن تكشف لا لأخي زوجها، ولا لعم زوجها، ولا لخال زوجها، وليس لها أن تكشف أيضًا لزوج أختها، ولا زوج خالتها، ولا زوج عمتها، كلهم أجانب بالنسبة إليها.\n\nإنما الكشف يكون لأبي زوجها، لجد زوجها، لأولاد زوجها، هؤلاء هم المحارم: أولاد الزوج، وأولاد أولاده، وأولاد بناته، هم المحارم، أما زوج الأخت، زوج العمة، زوج الخالة، هؤلاء ليسوا محارمًا، المحارم زوج بنتها، وزوج أمها، هؤلاء محارم.","link":"https://binbaz.org.sa/fatwas/3167/حكم-كشف-الوجه-لاخي-الزوج-واقاربه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1525.mp3","categories":["الخِطْبَة والاختيار ","النظر والخلوة والاختلاط","قضايا المرأة","الآداب والأخلاق"]},{"id":7153,"question":"ما حكم الجلوس مع بنات العم، وبنات الخال مع حضور المحرم؟","title":"حكم الجلوس مع بنات العم أو الخال","answer":"الجواب:\n\nإذا كن متسترات، ولا في فتنة؛ فلا بأس، أما إذا كان الحضور لأجل الفتنة ولأجل التمتع بالنظر إليهن وهن سافرات؛ لا يجوز هذا.\n\nأما الجلوس معهن للسلام عليهن، أو السؤال عن حال مريضهن، وهن متسترات متحجبات بعيدات عن الفتنة على طريق الحشمة؛ فلا بأس، هكذا المسلمون فيما بينهم.","link":"https://binbaz.org.sa/fatwas/3184/حكم-الجلوس-مع-بنات-العم-او-الخال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1542.mp3","categories":["الخِطْبَة والاختيار ","النظر والخلوة والاختلاط","قضايا المرأة","الآداب والأخلاق"]},{"id":7157,"question":"هل يجوز أن أصافح عمات وخالات زوجتي؟","title":"حكم مصافحة عمات وخالات الزوجة","answer":"الجواب:\n\nليس لك أن تصافح لا عماتها ولا خالاتها ولا أخواتها أيضًا، ليس لك ذلك، إنما هذا مع الأم، مع أمها، أو بنتها بعد الدخول بها، أما عماتها وخالاتها وأخواتها فليسوا محارم، وإنما تسلم عليهن بالكلام فقط، كيف حالكم؟ كيف أنتم؟ السلام عليكم، وعليكم السلام، من دون مصافحة.","link":"https://binbaz.org.sa/fatwas/3185/حكم-مصافحة-عمات-وخالات-الزوجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1543.mp3","categories":["الخِطْبَة والاختيار ","النظر والخلوة والاختلاط","قضايا المرأة","الآداب والأخلاق"]},{"id":7265,"question":"دبلة الخطوبة؟","title":"حكم دبلة الخطوبة","answer":"الجواب:\n\nالدبلة ما لها أصل، غلط، ولا وجه لها، هذه تلقوها عن مشابهة أعداء الله، الشبكة يسمونها الشبكة، هذه ما لها أصل.","link":"https://binbaz.org.sa/fatwas/3330/حكم-دبلة-الخطوبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1651.mp3","categories":["اللباس والزينة","الخِطْبَة والاختيار ","البدع والمحدثات"]},{"id":7335,"question":"تقدمت للعمل في إحدى المستشفيات كمترجم، وفي هذه المستشفى كما في المستشفيات الأخرى الاختلاط موجود بين الرجال والنساء، سؤالي: هو بحكم عملي اضطر إلى مخالطة النساء المرضى والعاملات، فما رأي فضيلتكم في هذا الموضوع، أفيدونا -جزاكم الله خيرًا- علمًا أنني في حاجة ماسة إلى هذه الوظيفة؟","title":"حكم العمل في أماكن الاختلاط","answer":"الجواب:  إذا كان عملك يجعلك تختلط بالنساء؛ فابتعد واحذر، احذر لئلا تُفترس، يفترسك الشيطان بواسطتهن، احذر. أما إذا كان عملك بعيدًا عنهن، إنما أنت مترجم لما يساق إليك، ويوصل إليك في مكتبك، تترجمه وتعطيهم إياه؛ فلا بأس، أما أنك تختلط بالنساء، بمريضات، وغير مريضات، وربما سبب لك ذلك مشاكل كثيرة، وأخطارًا كثيرة، وهن شبه عاريات، وكثير منهن لا يبالي بالستر والحجاب، أو كلهن، فأنت على خطر، فاحذر وابتعد، والرزق عند الله.","link":"https://binbaz.org.sa/fatwas/3414/حكم-العمل-في-اماكن-الاختلاط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1726.mp3","categories":["الخِطْبَة والاختيار ","النظر والخلوة والاختلاط","قضايا المرأة","الآداب والأخلاق"]},{"id":7379,"question":"نشأت يتيم الأب والأم، وتولى رعايتي عمي، فرباني وأحسن رعايتي، وذلك من صغري، وعمري سبع سنوات، وشاركته في ذلك امرأته الحنونة، فلبثت عندها حتى أصبح عمري عشرين عامًا، وعمي تولى رعايتي، وأنفق عليَّ أثناء دراستي رغم فقره، والسؤال هنا: هل يجوز أن تكشف علي امرأة عمي، أم لا يجوز؟ وأنا اعتبرها أخت بحيث أنها لم تحتجب مني قبل ذلك وظلت تكشف علي إلى آخره؟","title":"حكم الكشف والمصافحة لزوجة العم التي ربته","answer":"الجواب: هذا عمل طيب من عمك جزاه الله خيرًا، الذي أحسن إليك، ورباك، وأنفق عليك، فالعم مثل الأب لا يستغرب، العم بمنزلة الأب كما قال النبي ﷺ: إن عم الرجل صنو أبيه فإذا أحسن إليك ورباك وأنفق عليك؛ فهذا عمل مشكور، وعليك أن تدعو له وتشكره على هذا العمل، سواء كان حيًّا أو ميتًا.  وأما زوجته التي أحسنت إليك فهي بمنزلة أمك، ما هي أختك، بمنزلة الأم التي ربتك وأحسنت إليك، لكن لا تكشف لك، وليست محرمًا لك، لكن تدعو لها، وتشكرها على عملها الطيب مع زوجها، ولكن لا تخلو بها، ولا تكشف لك، بل تحتجب عنك، هي أجنبية إلا إذا كانت أرضعتك، أو أرضعتك بنتها، أو أختها؛ تكون خالة لك، لا بأس، إذا كان بينك وبينها رضاعة، إما أرضعتك هي وأنت صغير، أو أرضعتك أختها؛ تكون خالة لك، أو أرضعتك بنتها؛ تكون جدة لك، لا بأس، أما مجرد كونها ربتك ما تكون محرمًا لك، ولا تكشف لك، بل عليها أن تحتجب عنك وعليك أن لا تنظر إليها، ولكن عليك أن تشكرها وتحسن إليها، وتعرف قدرها، وإحسانها، وإحسان زوجها -عمك هذا- عليك؛ لأن النبي ﷺ يقول: من صنع إليكم معروفًا؛ فكافئوه، فإن لم تجد ما تكافئوه فادعوا له حتى تروا أنكم قد كافأتموه ويقول النبي ﷺ: من لا يشكر الناس لا يشكر الله. السؤال: وإن كانت كبيرة؟ الجواب: إلا إذا كانت عجوزًا يعني ما تشتهى، ولا تزين، ولا شيء مثل ما قال الله: وَالْقَوَاعِدُ مِنَ النِّسَاءِ اللَّاتِي لَا يَرْجُونَ نِكَاحًا فَلَيْسَ عَلَيْهِنَّ جُنَاحٌ أَنْ يَضَعْنَ ثِيَابَهُنَّ [النور:60] إذا كانت عجوزًا كبيرة، لا تتعاطى الزينة؛ فلا بأس، أما إذا كانت تتعاطى الزينة، ويظهر منها ما قد يميل الرجال إليها؛ فلا يجوز لها أن تكشف، وليس لأحد أن ينظر إليها. والمصافحة لا يصافح الرجل النساء لا، المصافحة بين الرجل والرجال، أو بين الرجل ومحارمه، كأمه وخالته، أما أن يصافح النساء لا، النبي ﷺ قال: إني لا أصافح النساء لا كبيرة ولا صغيرة، كل ساقطة لها لاقطة.","link":"https://binbaz.org.sa/fatwas/3462/حكم-الكشف-والمصافحة-لزوجة-العم-التي-ربته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1766.mp3","categories":["الخِطْبَة والاختيار ","النظر والخلوة والاختلاط","قضايا المرأة","الآداب والأخلاق"]},{"id":7392,"question":"لي أخت متزوجة وزوجها يجبرها على أن لا تحتجب من إخوانه، فهل يحق لي مقاطعتهم، علمًا بأنني نصحت لهم وللزوج خاصة، ولكن الزوج رفض، فماذا علي أنا؟ وماذا على الزوجة؟","title":"حكم كشف المرأة وجهها أمام إخوة زوجها","answer":"الجواب: عليها أن تحتجب ولو لم يرض، ليس لها طاعته في المعصية، يقول النبي ﷺ: إنما الطاعة في المعروف فإذا كان ضعيف الغيرة وأمرها أن تكشف لإخوانه وأعمامه وأصحابه وأصدقائه؛ فليس لها طاعته في ذلك -نسأل الله للجميع الهداية-.","link":"https://binbaz.org.sa/fatwas/3510/حكم-كشف-المراة-وجهها-امام-اخوة-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1814.mp3","categories":["الخِطْبَة والاختيار ","النظر والخلوة والاختلاط","قضايا المرأة","الآداب والأخلاق"]},{"id":7410,"question":"لي أخت متزوجة وزوجها يجبرها على أن لا تحتجب من إخوانه، فهل يحق لي مقاطعتهم، علمًا بأنني نصحت لهم وللزوج خاصة، ولكن الزوج رفض، فماذا علي أنا؟ وماذا على الزوجة؟","title":"حكم كشف المرأة وجهها أمام إخوة زوجها","answer":"الجواب: عليها أن تحتجب ولو لم يرض، ليس لها طاعته في المعصية، يقول النبي ﷺ: إنما الطاعة في المعروف فإذا كان ضعيف الغيرة وأمرها أن تكشف لإخوانه وأعمامه وأصحابه وأصدقائه؛ فليس لها طاعته في ذلك -نسأل الله للجميع الهداية-.","link":"https://binbaz.org.sa/fatwas/3510/حكم-كشف-المراة-وجهها-امام-اخوة-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1814.mp3","categories":["الخِطْبَة والاختيار ","النظر والخلوة والاختلاط","قضايا المرأة","الآداب والأخلاق"]},{"id":7668,"question":"سماحة الشيخ لدينا مجموعة كبيرة من الأسئلة، وهذه أربع رسائل للمرسلة (م . س) من الدمام، والمرسل زيدان خلف حسين بغداد العراق، وسالم محمد عامر العسيري من تهامة عسير، وسليم محمد الزهراني ، ونبدأ يا سماحة الشيخ برسالة المرسلة (م. س) من الدمام وتسأل عن مخاطبة الخطيب لخطيبها في التلفون.تقول أسألكم عن حكم محادثة أختي لخطيبها في التلفون، مع أنه ابن عمتي، وأنها تحدثه لعلم أبي وأمي وإخوتي جميعاً، وأن خطيبها دائم التردد على أبي يريد أن يعقد القران، ولكن أبي يؤخر لظروف، أفيدونا أفادكم الله؟","title":"حكم مخاطبة الرجل لمخطوبته","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، والصلاة والسلام على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد:\nفلا نعلم حرجاً في محادثة المرأة المخطوبة لخطيبها في بعض شئون النكاح، وفي بعض شئون عقد النكاح أو ما يتعلق بذلك من الأحاديث السليمة التي ليس فيها محرم ولا تعاون على محرم.\nأما إذا كان التحدث يدعو إلى ريبة أو يدعو إلى خلوة بها، أو إلى اتصال بها قبل عقد النكاح فهذا محرم ولا يجوز، وله أن ينظر إليها إذا دعت الحاجة إلى ذلك لكن من غير خلوة، ينظر إليها بحضرة أبيها وأمها ونحو ذلك، ولا يجوز الخلوة بها أبداً؛ لأن الشيطان إذا خلا الرجل والمرأة صار ثالثهما فلا يجوز.\nوأما الأحاديث التي لا تعلق لها بمصلحتهما بل بالجنس وما الجنس وما يدعو إلى أن يتصل بها اتصالاً غير جائز فهذا كله لا يجوز، وينبغي لأبيها أن يسارع بالعقد؛ حتى لا يقع شيء مما حرم الله، فينبغي أن يسارع بالعقد حتى تحل له ويحل لها، وحتى يتيسر البدار ببنائه عليها ودخوله بها. نعم.","link":"https://binbaz.org.sa/fatwas/4863/حكم-مخاطبة-الرجل-لمخطوبته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_039/03901.mp3","categories":["الخِطْبَة والاختيار "]},{"id":7671,"question":"هذه مشكلة عائلية يعرضها سالم محمد عامر العسيري من تهامة عسير بلاد آل خنارش قرية العلكة يقول فيها: أفيدكم أنني شاب أبلغ من العمر تسعة عشر سنة حسن السيرة مع أهلي وعشيرتي، تزوجت من بنت خالي على رضا من الطرفين أنا وهي، ولم يمض على زواجنا أكثر من أسبوع حتى بدأت مشاكل أهلها تزداد يوم بعد يوم، حتى منعوها من مواجهتي قائلين: إنها مريضة ولا تستطيع مواجهتي، ثم أحضر مرات أخرى وأجدهم كل وقت يدبرون عذر للتخلص مني، كما أن زوجتي مجبورة على تنفيذ كل كلمة يوجهونها إليها، أنا محتار قررت أن أطلق زوجتي ولكن زوجتي لا تريد الطلاق، وأنا لا أطيق فراقها ولا أقدر أعرض مشكلتي على المحكمة بصفة والدها خالي شقيق والدتي، والناس يعتبرون ذلك عاراً، فما الحل المناسب الذي ترونه موافقاً يا فضيلة الشيخ؟","title":"نصيحة لولي منع ابنته من زوجها","answer":"الجواب: ننصح السائل بالصبر، وأن لا يعجل في الطلاق، وأن يخاطب خاله بالتي هي أحسن، ويطلب منه تمكينه من زوجته، وإعادتها إلى بيت الطاعة، وأن يتوسل إلى ذلك بالأقارب الطيبين والجيران الطيبين حتى يشيروا على والدها وينصحوه ويعيدها إلى زوجه، هذا الذي ننصح به.\nكما ننصح والدها بأن يتقي الله، وأن يعيد المرأة إلى زوجها، إلا أن يكون هناك عذر شرعي فيبين للزوج هذا العذر، فإما أن يفارق وإما أن يذهب معه إلى المحكمة، وفي المحكمة البركة والخير، أما أن يمنعها من زوجها بغير وجه شرعي فهذا حرام وظلم، والله جل وعلا يقول في كتابه العظيم: وَمَنْ يَظْلِمْ مِنْكُمْ نُذِقْهُ عَذَابًا كَبِيرًا [الفرقان:19]، ويقول سبحانه: وَالظَّالِمُونَ مَا لَهُمْ مِنْ وَلِيٍّ وَلا نَصِيرٍ [الشورى:8].\nوالنبي يقول ﷺ: اتقوا الظلم فإن الظلم ظلمات يوم القيامة، فالواجب على خال هذا الزوج وهو أب المرأة، الواجب عليه أن يتقي الله، وأن يعيد المرأة إلى زوجها، وأن يتوسط بينهما في الخير، وأن ينصح للجميع، وأن يكون عوناً لهما على الاستقامة، والسيرة الحسنة، والمعاشرة الطيبة بينهما هذا هو الواجب عليه، فإن كان هناك أمور أخرى قد أخفاها السائل تحتاج إلى حل وسط من الأجاويد والإخوان الطيبين من يحلوا النزاع بينهما، فإن أعضلت المسألة ولم يتيسر ذلك فبالإمكان الاتصال بالمحكمة، والنظر في أمرهما من جهة المحكمة، أما منعها بغير حق فهذا لا يجوز له. نعم.","link":"https://binbaz.org.sa/fatwas/4870/نصيحة-لولي-منع-ابنته-من-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_039/03904.mp3","categories":["الخِطْبَة والاختيار ","نصائح وتوجيهات"]},{"id":7719,"question":"هذه رسالة من الرياض، من مرسلتها أخت محمد ، تقول في سؤالها: أريد منكم أن توجهوا كلمة للأم إذا جاءت لتأخذ رأي ابنتها للمتقدم، كيف توضح ذلك، نريد التوجيه من فضيلتكم، وفقكم الله؟","title":"ضرورة علم المخطوبة بحال الخاطب","answer":"الجواب: يشرع للأم ولغير الأم كالأب والأخ عندما يستشير ابنته أو أخته في الزواج يقول لها: خطبك فلان، وصفته كذا وكذا، فلان بن فلان، من أسرة صفتها كذا وكذا، يشرح لها حالة الرجل وأسرته، وأنهم أناس معروفون بالديانة والخير، وحالهم من جهة الدنيا أيضاً لا بأس، وينصح لها بما يرى من قبول الخطبة وعدم ذلك، يعني: هو مؤتمن، فالواجب أن يبين لها الحقيقة، ولا يلبس عليها الأمر، فلا يقول: أنه طيب وهو ليس بطيب، ولا يقول: إنه جميل وهو ليس بجميل، ولا يقول: إنه بصير وهو أعمى، يبين لها الحقيقة على ما هي عليه، ويشرح لها الواقع كما هو، وينصح لها في أخذه أو عدم أخذه، هذا هو الواجب على الأم والجدة والأخت والخالة والأب والعم والأخ، كل واحد من هؤلاء إذا أراد يبين لموليته أو لمن له بها صلة يبين الحقيقة على الوجه الذي علمه من الخاطب، وإن تيسر أن يراها وتراه فهو أفضل؛ حتى لا تبقى شبهة ولا تبقى ريبة، قال النبي ﷺ: إذا خطب أحدكم المرأة فإن استطاع أن ينظر منها إلى ما يدعوه إلى نكاحها فليفعل؛ فإن ذلك أقرب إلى أن يؤدم بينهما يعني: أقرب إلى أن يتفقا، ويحصل بينهما الوئام، وثبت عنه صلى الله عليه وسلم أنه أخبره رجل أنه خطب من بني فلان، فقال: هل نظرت إليها؟ قال: لا، قال: اذهب فانظر إليها.\nفالمقصود: أن الأفضل أن ينظر إليها وتنظر إليه إذا تيسر ذلك، ولكن يكون بدون خلوة، بأن يكون معهما أحد، إما أمها أو أختها الكبيرة أو أبوها أو عمها أو أخوها أو ما أشبه ذلك، لا يخلو الخاطب بالمخطوبة، ينظر إليها لكن بحضور من تزول معه الخلوة، ويؤمن معه ما يخاف منه من الخلوة. نعم.","link":"https://binbaz.org.sa/fatwas/4918/ضرورة-علم-المخطوبة-بحال-الخاطب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_031/03105.mp3","categories":["الخِطْبَة والاختيار "]},{"id":8191,"question":"هذه أيضاً من الأخت المرسلة المعذبة الحائرة (م. م. ن) من مكة المكرمة، تقول في رسالتها: أرجو من البرنامج أن يعرض رسالتي هذه على فضيلة الشيخ عبد العزيز بن عبد الله بن باز وفقه الله لما يحبه ويرضاه، أنا فتاة مؤمنة بالله وبوحدانيته، مؤدية لطاعاته، أسعى إلى كل ما يقرب إليه، إلا أنني أعيش في دوامة مستمرة من أمري، أعيش في صراع دائم مع نفسي، هذه النفس الأمارة بالسوء والتي هي سبب حيرتي وعذابي في حياتي، والتي لا أجد فيها الطمأنينة أبداً في جميع أعمالي، وخاصة العبادة، وعلى رأسها الصلاة، فعندما أقوم لتأديتها لا أجد ذلك الخشوع والخضوع المطلوبين فيها، تراودني أفكار شتى تجعلني أقطع القراءة، لكن أتعوذ من الشيطان، وأستغفر الله ثم أكمل، ولا ألبث لحظات إلا وأعود لمثلها، ولا أزال كذلك حتى أنتهي منها، وبعدها أشعر أن صلاتي غير مقبولة، وأن جميع أعمالي غير مقبولة مني، بكيت كثيراً واستغفرت كثيراً، وتبت إلى الله أكثر من مرة، ولكن أجد نفسي تقودني إلى المعاصي، فأنا الآن أعيش في عذاب وقلق وحيرة وخوف، أخاف أن ينقضي عمري وأنا على هذه الحالة، أخاف من أن تنتهي حياتي ولم أغتنم منها شيء، علماً بأنني لم أكن كذلك من قبل، فأرجو من فضيلته أن يشير علي بما يجب فعله، حتى أعود كما كنت سابقاً، وفقكم الله لما يحبه ويرضاه؟","title":"وسائل علاج الوساوس الشيطانية أثناء العبادة وغيرها","answer":"الجواب: أولاً: أسأل الله سبحانه للسائلة أن يوفقها لما فيه رضاه، وأن يصلح قلبها وعملها، وأن يرشدها إلى خير الأمور، وأن يهبها ثباتاً واستقامة وصلاحاً ورشداً، وأن يدلها على الخير الذي به الطمأنينة، وبه السعادة العاجلة والآجلة. ونصيحتي أن تكثري أيها السائلة من قراءة القرآن الكريم، بالتدبر والتعقل في الأوقات المناسبة، مع مطالعة كتب السنة وكتب التفسير التي تنفعك، مثل: رياض الصالحين، مثل: بلوغ المرام، مثل: الوابل الصيب، مثل: تفسير ابن كثير ، والبغوي ، وابن جرير ، هذه التفاسير المفيدة، تفسير الشوكاني ، حتى تستفيدي وحتى تشغلي الوقت بما ينفعك.\nوأمر آخر وهو مجالسة الأخيار من أهل بيتك، والأنس بهم، من أب وأم أو أخوات صالحات، تشغلي به بعض الوقت أيضاً، وإذا كنت ليست ذات زوج أن تحرصي على الزواج، ولو أن تخطبيه أنت، تنظرين من أقاربك من هو طيب، ومن هو صالح لك من أبناء العم، أو أبناء الخال، أو غيرهم ممن تعرفين، ثم تطلبين من أبيك أو غيره من أوليائك أن يتوسط بهذا، وتقولين: إنه بلغني عنه كذا، وبلغني عنه كذا من غير ريبة، بل بالسؤال عنه، والتعرف عليه، فإذا عرفت أنه صالح، وأنه جيد قلت لأبيك أو غيره من أوليائك: إنك تطلبين فلان حتى يتزوجك، وتنصحيه بألا يتكلف في المهور، ولا في الولائم، وأن يتسامحوا معه في المهر وفي الوليمة، كل هذا من أسباب الهدوء، ومن أسباب الثبات، ومن أسباب زوال هذه الوساوس والأفكار الرديئة. وإن كنت ذات زوج فالحمد لله، وعليك أن تعيشي معه طيباً، وأن تعامليه بالخير، وأن تعاشريه بالمعروف، وأن تجتهدي في أسباب الألفة معه والمحبة، وقضاء الوطر الشرعي، مع العناية بما تقدم من قراءة القرآن الكريم بتدبر، كثرة الذكر والاستغفار، كثرة التعوذ بالله من الشيطان الرجيم، الإكثار من قول: لا حول ولا قوة إلا بالله، ومع المطالعة للكتب النافعة المفيدة، كل هذا من أسباب زوال ما ذكرت من القلق، والوساوس التي قد تضرك، وأسأل الله لك الهداية والتوفيق، وصلاح النية والعمل.\nالمقدم: شكراً أثابكم الله.","link":"https://binbaz.org.sa/fatwas/6006/وساىل-علاج-الوساوس-الشيطانية-اثناء-العبادة-وغيرها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_093/09307.mp3","categories":["الخِطْبَة والاختيار ","نصائح وتوجيهات"]},{"id":8283,"question":"الرسالة التالية باعثتها إحدى الأخوات من العراق بغداد تقول: إيمان كاظم جبار تقول: إنها شابة وموظفة وتبلغ من العمر ثمان وعشرين سنة وغير متزوجة، قدم لها شاب لا يعرف الكتابة ولا القراءة ويعمل نجارا، فقالت للشاب: روح تعلم كيف تكتب اسمك ثم تقدم للخطبة، وحينئذ عاد هذا فانتحر -كما تقول- وبدأ أصدقاؤها وأقرباؤها يلومونها على هذه اللفظة التي طلعت منها، حتى إن البعض قال: لقد ارتكبت رقبة، وهي الآن في قلق كبير، بم تنصحونها سماحة الشيخ؟","title":"حكم رفض المرأة الزواج من العامي الذي لا يكتب","answer":"الجواب: ليس عليك بأس يا أختي، ليس عليك بأس، نصحتِه يتعلم شيئاً من الكتابة وليس عليك بأس، وكونه انتحر هذا من سخافة عقله ومن جهله وقلة بصيرته، أنت ما قلت له إلا خيرًا، وتعلم الكتابة القليلة ميسرة، ميسر ليس بصعب، كونه يتعلم في الكتاب أو عند بعض أصحابه وإخوانه، كل هذا ميسر.\nفنصيحتك له إذا قلت له: تعلم الكتابة أو تعلم وتفقه في دينك، أو تعلم القرآن، كل هذا طيب ليس فيه شيء، وليس عليك بأس من ذلك، وإثمه عليه في انتحاره، أما أنت فليس عليك شيء واطمئني ودعي قول الناس.\nالمقدم: بارك الله فيكم. هنا رسالة وصلت إلى البرنامج من أحد الإخوة السودانيين: حيدر عبد الله أبو دياب يقول...\nالشيخ: نريد أن نزيدها.\nالمقدم: تفضل، تفضل.\nالشيخ: ونوصيك أيضًاً ونوصيك ألا تردِّي الطيب ولو كان عاميًّا لا يكتب ولا يقرأ، نوصيك في المستقبل، إذا خطبك الطيب المعروف بالاستقامة في دينه وصلاته وسمعته الحسنة فلا ترديه وإن كان لا يقرأ ولا يكتب، والنصيحة بعد ذلك بعد الزواج بينك وبينه، فلا تردي الطيب وإن كان لا يقرأ ولا يكتب، وفق الله الجميع.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/6091/حكم-رفض-المراة-الزواج-من-العامي-الذي-لا-يكتب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_100/10005.mp3","categories":["نصائح وتوجيهات","الخِطْبَة والاختيار ","نكاح الكفار"]},{"id":8284,"question":"الرسالة التالية باعثتها إحدى الأخوات من العراق بغداد تقول: إيمان كاظم جبار تقول: إنها شابة وموظفة وتبلغ من العمر ثمان وعشرين سنة وغير متزوجة، قدم لها شاب لا يعرف الكتابة ولا القراءة ويعمل نجارا، فقالت للشاب: روح تعلم كيف تكتب اسمك ثم تقدم للخطبة، وحينئذ عاد هذا فانتحر -كما تقول- وبدأ أصدقاؤها وأقرباؤها يلومونها على هذه اللفظة التي طلعت منها، حتى إن البعض قال: لقد ارتكبت رقبة، وهي الآن في قلق كبير، بم تنصحونها سماحة الشيخ؟","title":"حكم رفض المرأة الزواج من العامي الذي لا يكتب","answer":"الجواب: ليس عليك بأس يا أختي، ليس عليك بأس، نصحتِه يتعلم شيئاً من الكتابة وليس عليك بأس، وكونه انتحر هذا من سخافة عقله ومن جهله وقلة بصيرته، أنت ما قلت له إلا خيرًا، وتعلم الكتابة القليلة ميسرة، ميسر ليس بصعب، كونه يتعلم في الكتاب أو عند بعض أصحابه وإخوانه، كل هذا ميسر.\nفنصيحتك له إذا قلت له: تعلم الكتابة أو تعلم وتفقه في دينك، أو تعلم القرآن، كل هذا طيب ليس فيه شيء، وليس عليك بأس من ذلك، وإثمه عليه في انتحاره، أما أنت فليس عليك شيء واطمئني ودعي قول الناس.\nالمقدم: بارك الله فيكم. هنا رسالة وصلت إلى البرنامج من أحد الإخوة السودانيين: حيدر عبد الله أبو دياب يقول...\nالشيخ: نريد أن نزيدها.\nالمقدم: تفضل، تفضل.\nالشيخ: ونوصيك أيضًاً ونوصيك ألا تردِّي الطيب ولو كان عاميًّا لا يكتب ولا يقرأ، نوصيك في المستقبل، إذا خطبك الطيب المعروف بالاستقامة في دينه وصلاته وسمعته الحسنة فلا ترديه وإن كان لا يقرأ ولا يكتب، والنصيحة بعد ذلك بعد الزواج بينك وبينه، فلا تردي الطيب وإن كان لا يقرأ ولا يكتب، وفق الله الجميع.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/6091/حكم-رفض-المراة-الزواج-من-العامي-الذي-لا-يكتب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_100/10005.mp3","categories":["نصائح وتوجيهات","الخِطْبَة والاختيار ","نكاح الكفار"]},{"id":8374,"question":"هل يجوز للخاطب عندما يخطب لابنه أو أحد أقربائه زوجة أن يخفي ما في ابنه أو غيره من عيوب، كأن يكون أعرج، أو أعمى؟","title":"حكم إخفاء عيوب الخاطب أو المخطوبة","answer":"الجواب: ليس له أن يخفي العيوب، وليس لأهل المرأة أن يخفوا عيوبها، الواجب البيان، لأن المسلم أخو المسلم والرسول ﷺ يقول: الدين النصيحة ويقول جرير : بايعت النبي ﷺ على إقام الصلاة وإيتاء الزكاة والنصح لكل مسلم.\nفليس له أن يخفي عيوبه، وليس لها أن تخفي عيوبها، وليس لأهل المرأة أن يخفوا عيوبها، بل عليهم أن يوضحوا للرجل على ما هي عليه، صحيحة أو مريضة، عوراء أو عمياء، عرجاء أو غير ذلك، حتى يقدم على بصيرة. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6223/حكم-اخفاء-عيوب-الخاطب-او-المخطوبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_114/11414.mp3","categories":["الخِطْبَة والاختيار ","نصائح وتوجيهات"]},{"id":8396,"question":"أولى رسائل هذه الحلقة سماحة الشيخ رسالة وصلت إلى البرنامج من الأخ (م. ع. أ) سوداني مقيم في المدينة المنورة، أخونا يقول: سبق أن قلت لوالدي: زوجني بابنة خالي؛ لأنها يتيمة، إلا أن والدي أصر على تزويجي بابنة عمي؛ لأن عمي له ثروة ضخمة، كما يقول سماحة الشيخ، ويرجو التوجيه لو تكرمتم؟","title":"مراعاة ذات الدين عند إرادة الزواج","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله رب العالمين، والصلاة والسلام على عبده ورسوله، نبينا وإمامنا وسيدنا محمد بن عبد الله، وعلى آله وأصحابه ومن سلك سبيله واهتدى بهداه إلى يوم الدين.\nأما بعد:\nفالواجب عليك وعلى أبيك العناية بالزوجة الصالحة، وعدم النظر إلى المال، المهم أن تكون المرأة صالحة مستقيمة في دينها، فعليك أن تتحرى أنت ووالدك هذا الصنف من النساء.\nأما مراعاة المال فلا تنبغي أن تكون مقصودةً، وإنما المقصود الأعظم المهم هو مراعاة الدين والأخلاق، كما قال النبي ﷺ: فاظفر بذات الدين تربت يداك يقول ﷺ: تنكح المرأة لأربع: لمالها، ولحسبها، ولجمالها، ولدينها فاظفر بذات الدين تربت يداك فإذا تيسر الدين فما معه بعد ذلك من جمال أو مال أو حسب خير إلى خير، لكن الأهم الأول هو كونها في نفسها صالحة مستقيمة حتى تنفعك، وحتى تأمنها على عرضها، وعلى بيتك، وعلى مالك، وعلى كل شئونك، فإذا كانت بنت خالتك أنسب في الدين فينبغي للوالد أن يوافقك على ذلك، وإن كانت بنت عمك أنسب فينبغي لك أن توافق أباك على ذلك، وإن لم تكونا مناسبتين فالتمسا غيرهما، التمسا امرأةً أخرى، وليس من اللازم أن تكون قريبة بنت خال أو بنت عم ولو بعيدة من الناس من سائر الناس، هذا هو الذي ينبغي لك ولأبيك، التماس المرأة الطيبة، وإذا كانت بنت عمك وبنت خالك متقاربتين، فالأولى أن تقبل ما رآه والدك، وأن تخضع لقول والدك إذا كانتا متقاربتين في الدين والأخلاق والجمال ونحو ذلك، بكل حال كونك توافق والدك أمر مطلوب، لكن بشرط أن تكون المرأة التي أشار بها صالحة مناسبة، وفق الله الجميع. نعم.","link":"https://binbaz.org.sa/fatwas/6262/مراعاة-ذات-الدين-عند-ارادة-الزواج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_117/11701.mp3","categories":["الخِطْبَة والاختيار ","نصائح وتوجيهات"]},{"id":8628,"question":"ا لسؤال: هذه رسالة وردتنا من السائل (ع. عبد الحميد مرسي ) مصري يعمل بالأردن، يقول: خطبت فتاة منذ ثلاثة أعوام، وقدمت لها شبكة وقمت بتجهيز كل شيء من الجهاز وخلافه، وفجأة حدث رفض من ناحية والدتها، وأصبح زواجي منها مستحيل، مع العلم أن الفتاة ليس لها أي ذنب في ذلك، هل لي الحق في استرداد كل ما قدمته من ذهب وخلافه أم لا؟","title":"حكم استرداد الخاطب ما دفعه للمخطوبة","answer":"الجواب: نعم، لك -يا أخي- الحق فيما قدمت؛ لأنك قدمته ليعطوك البنت، فإذا منعوا البنت وجب عليهم رد ما قدمت إليهم من قليل وكثير، والواجب على أمها أن تتقي الله، إذا كنت أهلاً للبنت في دينك وليس هناك مانع ديني والمرأة راضية -البنت راضية- وليس هناك موانع شرعية فالواجب أن تعين على الخير وأن لا تمنع زواج بنتها منك، هذا هو الواجب؛ لأن تزويج البنات من أهم المهمات لما فيه من العفة لهن والحرص على سلامتهن من الفساد، وهكذا الشباب تزويجهم من أهم المهمات لما في ذلك من إبعاده عن الخطر وتمكينه من غض البصر وإحصان الفرج، وقد قال النبي ﷺ في الحديث الصحيح: يا معشر الشباب! من استطاع منكم الباءة فليتزوج؛ فإنه أغض للبصر، وأحصن للفرج، ومن لم يستطع فعليه بالصوم فإنه له وجاء متفق على صحته، هذا الحديث الصحيح عن رسول الله عليه الصلاة والسلام يبين لنا أن المبادرة بالزواج للشباب أمر لازم، والصحيح: أنه فرض، لما فيه من الخير الكثير والمصالح العظيمة للذكر والأنثى.\nفعلى الآباء والإخوة والأقارب أن يساعدوا في هذا، وأن يعينوا الشاب على الزواج ويعينوا الفتاة على الزواج، وأن لا يضعوا العراقيل، وكذلك ينبغي التساهل في المهور والولائم؛ لأنها عقبة أيضاً، فالواجب على الجميع التعاون على الخير والتواصي بالحق، فالأم تساعد، والأب يساعد، والعم يساعد، والأخ يساعد، لا من جهة المهر وتخفيفه، ولا من جهة الولائم، ولا من جهة توابع المهر، كلها ينبغي فيها التخفيف ويشرع فيها التخفيف والإعانة على الخير.\nوإذا كانت الفتاة جيدة طيبة في دينها فينبغي المسارعة إلى خطبتها، وإذا كان الرجل طيباً فتنبغي المسارعة إلى قبوله وتلبية طلبه، والمبادرة إلى تزويجه؛ لأن الشاب الصالح غنيمة، والفتاة الصالحة غنيمة، فلا ينبغي للمؤمن إذا كان أباً أو أماً أن يعرقل هذه الأمور، نسأل الله للجميع الهداية.\nوبكل حال إذا خطب الإنسان وقدم المهر والكساوي وغير ذلك ثم ردوه يلزمهم أن يعطوه كلما أخذوا منه، يلزمهم أن يردوا عليه كلما أخذوا منه من قليل أو كثير إلا إذا سمح عن شيء. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6766/حكم-استرداد-الخاطب-ما-دفعه-للمخطوبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_211/21107.mp3","categories":["الخِطْبَة والاختيار ","نصائح وتوجيهات"]},{"id":8951,"question":"الرسالة التالية باعثتها إحدى الأخوات المستمعات تقول: (أ. أ. ع) من الشرقية، أختنا لها مجموعة من الأسئلة بدأت رسالتها تقول: أولًا أشكر البرنامج على ما يقدمه لنا من فتاوى قيمة، وجزى الله العلماء الأفاضل خير الجزاء على تفضلهم بالإجابة على أسئلتنا وجزاكم الله خيرًا.أرجو عرض أسئلتي الآتية على سماحة الشيخ عبدالعزيز بن باز: هل لبس الدبلة للنساء بدعة نصرانية؛ لأنني قرأت بأن دبلة الخطبة أو الزواج للرجل وإن كانت فضة وأيضًا للمرأة بدعة نصرانية، هل هذا صحيح؟","title":"حكم لبس دبلة الخطبة والزواج","answer":"الجواب: الدبلة التي تسأل عنها السائلة لا نعلم لها أصلًا والذي يظهر لنا من ذلك أن فيها تشبهًا بالكفرة؛ لأنها من عادتهم فيما بلغنا فلا ينبغي اتخاذها، فإن الإشارة إلى الزواج تكون بالخطبة والاتفاق بين الخاطب والمخطوب منهم ويكفي ذلك من غير حاجة إلى الدبلة، ومتى تم الأمر بالعقد الشرعي انتهى كل شيء، أما الدبلة فلا حاجة إليها ولا حاجة إلى التشبه بأعداء الله، لا من النصارى ولا من غيرهم، والواجب البعد عن مشابهة أعداء الله في كل شيء. نعم.","link":"https://binbaz.org.sa/fatwas/7108/حكم-لبس-دبلة-الخطبة-والزواج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_173/17302.mp3","categories":["اللباس والزينة","الخِطْبَة والاختيار ","البدع والمحدثات"]},{"id":9220,"question":"أختنا تسأل أيضاً عن قضايا مختلفة فتقول في القضية الأولى: ما حكم المكالمة الهاتفية بين الخاطب والمخطوبة، والقصد كما يقولون: هو التعارف قبل الارتباط بالزواج، وإذا كانوا صائمين هل يتغير الحكم، وهذا يوجد بكثرة في مجتمعنا الإسلامي، والمكالمات بريئة في ظاهرها وحسب كلامهم، وهذا السؤال نابع من الرغبة في التمسك بتعاليم ديننا؟","title":"حكم المكالمة الهاتفية بين الخاطب والمخطوبة","answer":"الجواب: لا نعلم حرجاً في الكلام بين الخاطب والمخطوبة إذا كان كلاماً بريئاً لا يجر إلى شر وإنما يقصد منه التعرف منه عليها ومنها عليه لا بأس في هذا، تسأله عن حاله وعن أعماله وعن ديانته ونحو ذلك وهو يسألها عن مثل ذلك لقصد التوثق من الإقدام على هذا النكاح فلا حرج في هذا، أما إن كان القصد سوى ذلك من التمتع بصوته وصوتها أو المواعيد التي قد تجر إلى الفاحشة فهذا لا يجوز، فالواجب على الخاطب والمخطوبة أن يتحريا الشيء الذي لابد منه في المخاطبة للتعرف فقط، أما ما يخشى منه الفتنة فالواجب اجتنابه.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7380/حكم-المكالمة-الهاتفية-بين-الخاطب-والمخطوبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_153/15302.mp3","categories":["الخِطْبَة والاختيار ","نصائح وتوجيهات"]},{"id":9303,"question":"وهذه رسالة وردت إلى البرنامج من سائلين سودانيين يقيمان في المدينة، هما: مختار نور الدين وسيف الدين الطيب، يقولان: نرجو أن تفتونا في شخص جامع خطيبته قبل عقد النكاح فحملت منه، فأخبرت خطيبها فأسرع وأتم عقد النكاح ثم رزقهم الله بمولود، ما حكم هذا المولود من ناحية الشرع بالرغم من أن الأب معترف به؟","title":"حكم من واقع خطيبته قبل عقد الزواج","answer":"الجواب: هذا المولود ولد زنا؛ لأن جماعه لها قبل أن يتم العقد منكر وزنا، فلا يلتحق به ولا يكون ولداً له، وإنما ينسب إلى أمه، أو ينسب إلى عبد الله أو عبد اللطيف، أو عبد الملك من باب الستر عليه في المستقبل.\nفالمقصود: أنه لا يلحق بأبيه؛ لأنه ولد زنا، ولكن ينسب إلى أمه ويضاف إليها، وعليهما التوبة جميعاً، على المرأة والرجل التوبة إلى الله  وتجديد النكاح؛ لأن العقد وقع في حال حملها من الزنا، فالواجب أن يجدد النكاح بعد وضعها الحمل، يجدده وليها بعد توبتهما جميعاً إلى الله ، ونسأل الله للجميع الهداية والتوفيق للتوبة النصوح.\nالمقدم: وإذا كان إلى الآن لم يجدد العقد يفارقها؟\nالشيخ: عليه أن يفارقها وأن يمتنع منها حتى يجدد النكاح، عليه أن يمتنع ويقف عن اتصاله بها حتى يجدد النكاح من وليها. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/7456/حكم-من-واقع-خطيبته-قبل-عقد-الزواج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_236/23602.mp3","categories":["الخِطْبَة والاختيار "]},{"id":9382,"question":"سؤال بقي لأخينا (د. م. م) يقول فيه: إذا أردت الزواج من بنت وهي ملتزمة بالحجاب ولكن ليست من منطقتي ولا أعرف هل هي جميلة أم لا، هل يصح النظر إليها إذا كان قد عزمت على الزواج منها، وكيف يكون ذلك جزاكم الله خيرًا؟","title":"حكم نظر الرجل إلى المرأة التي يريد خطبتها","answer":"الجواب: نعم، يشرع لك النظر إليها، إذا خطبت امرأة أو أردت أن تخطبها يشرع لك النظر إليها إذا تيسر ذلك، النبي ﷺ قال: إذا خطب أحدكم المرأة فإن استطاع أن ينظر منها إلى ما يدعوه إلى نكاحها فليفعل وذكر له رجل أنه خطب امرأة فقال: أنظرت إليها؟ قال: لا، قال: اذهب فانظر إليها فالمشروع لك أن تنظر إليها إن تيسر ذلك، وإلا ففي إمكانك تبعث من ثقات النساء، أو من محارمها إن كنت تعرف محارمها من يعطيك الخبر، فتبعث المرأة من أقاربك كأمك وخالتك وعمتك أو أختك تنظر إليها ثم تعطيها صفاتها، أو تسأل محارمها يعطونك صفاتها، وإذا تيسر لك النظر إليها من دون خلوة فلا بأس، تطلب من أبيها أو أمها أو أخيها أو نحو ذلك أن يسمح لك بالنظر إليها لكن من دون خلوة، فتنظر إليها بحضرة أبيها أو أمها أو أخيها أو غيرهم من الناس من دون خلوة. نعم.","link":"https://binbaz.org.sa/fatwas/7546/حكم-نظر-الرجل-الى-المراة-التي-يريد-خطبتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_187/18705.mp3","categories":["الخِطْبَة والاختيار ","النظر والخلوة والاختلاط","قضايا المرأة","الآداب والأخلاق المحمودة"]},{"id":9649,"question":"السؤال الرابع في رسالة الأخ (م. ر عبد الرب ) من عدن يقول فيه:شاب مسلم يريد الزواج من فتاة لا يعلم هي هل تصلي أم لا ؟ هل يجوز ذلك الزواج وما حكم ذلك، أفيدونا أفادكم الله؟","title":"حكم خطبة امرأة لا يُعلم أتصلي أم لا","answer":"الجواب: لابد أن يتثبت في الأمر؛ يسأل عنها أهل الخبرة، فإن الزواج من الكافرة لا يجوز والله يقول سبحانه: لا هُنَّ حِلٌّ لَهُمْ وَلا هُمْ يَحِلُّونَ لَهُنَّ [الممتحنة:10] ومن ترك الصلاة كفر على الصحيح من أقوال العلماء ولو كان مقرًا بالوجوب، إذا تركها تهاونًا وكسلًا كفر كما قال النبي ﷺ: بين الرجل وبين الكفر والشرك ترك الصلاة وقال عليه الصلاة والسلام: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر.\nفإذا كانت لا تصلي لا يتزوجها، وأما إذا عرف أنها تصلي وجيدة يتزوجها قال النبي ﷺ: تنكح المرأة لأربع لمالها ولجمالها ولحسبها ولدينها فاظفر بذات الدين تربت يداك، فذات الدين مطلوبة ... الصلاة التي هي أعظم الأركان وأهمها بعد الشهادتين. نعم.","link":"https://binbaz.org.sa/fatwas/7815/حكم-خطبة-امراة-لا-يعلم-اتصلي-ام-لا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_194/19411.mp3","categories":["حكم الصلاة وأهميتها","الخِطْبَة والاختيار ","بر الوالدين"]},{"id":9662,"question":"السؤال الثاني في رسالة الأخت إستبرق من العراق تقول فيه: إذا تقدم الشاب لخطبة فتاة في هذه الحالة هل يجب أن يراها، وأيضًا هل يصح أن تكشف الفتاة عن رأسها لتبين جمالها أكثر لخاطبها أفيدونا أفادكم الله؟","title":"حكم رؤية الخاطب للمخطوبة وكشف شعرها للخاطب","answer":"الجواب: لا بأس لكن لا يجب يستحب، يستحب أن يراها وتراه؛ لأن هذا أقرب إلى الوئام، النبي ﷺ أمر من خطب أن ينظر، فإذا كشفت له وجهها ويديها ورأسها فلا بأس على الصحيح، قال بعض أهل العلم: يكفي الوجه والكفان ولكن الصحيح أنه لا بأس بكشف الرأس والقدمين أيضًا حتى يستكمل محاسنها، فلها أن تنظر إليه وله أن ينظر إليها؛ لأن هذا أقرب إلى يؤدم بينهما كما جاء به الحديث؟ نعم، ينبغي أن يكون هذا من دون خلوة بل يكون معهما أبوها أو أخوها أو امرأة أخرى، لا يخلو بها. نعم.","link":"https://binbaz.org.sa/fatwas/7824/حكم-روية-الخاطب-للمخطوبة-وكشف-شعرها-للخاطب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_194/19414.mp3","categories":["الخِطْبَة والاختيار ","نصائح وتوجيهات"]},{"id":9783,"question":"أخيراً لصاحبنا هذا من السودان محمد نصر الدين يقول: خطبت ابنة عمي خطوبة رسمية، والخطوبة عندنا تطول كما تعلمون وسافرت وطلبت منها بعدما سافرت إرسال صورة لها، وفعلاً أرسلتها إلي، هل علي إثم في ذلك وما هي الكفارة؟","title":"طلب الخطيب من مخطوبته صورة لها","answer":"الجواب: نعم لا يجوز طلب إرسال الصورة، وعليك التوبة إلى الله هذا الكفارة، أن تتوب إلى الله توبة صادقة بالندم على ما فعلت والعزم ألا تعود إلى ذلك وتمزيق الصورة، هذا هو الواجب عليك، ليس لها أن ترسل لك صورة وليس لك أن ترسل لها صورة، بل لا بأس أن تنظر إليها إذا خطبتها أو أردت خطبتها لا بأس أن تنظر إليها، الرسول ﷺ أمر بهذا قال: انظر إليها ... فانظر إليها.\nفالمقصود: أن النظر إلى المخطوبة لا بأس من دون خلوة، بل بحضرة أبيها أو أمها أو أخيها من دون خلوة، ينظر إلى وجهها وما ظهر منها كأطرافها أو شعرها لا بأس، ولكن ليس له الخلوة بها ولا الخروج معها في السيارة كما يفعل بعض الناس مع مخطوبته يتمشى معها في البلد أو في الحدائق هذا منكر ووسيلة إلى الفساد، وإنما ينظر إليها بحضرة وليها أو أمها أو أخيها ونحو ذلك، حتى ينظر منها ما يرغبه فيها أو ينفره منها، وليس له أخذ الصورة منها وليس لها أن تطلب صورته، كلاهما ممنوع. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7955/طلب-الخطيب-من-مخطوبته-صورة-لها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_259/25908.mp3","categories":["الخِطْبَة والاختيار ","نصائح وتوجيهات"]},{"id":10038,"question":"المستمع محمد نصر الدين مصطفى من السودان بعث يقول: خطبت ابنة عمي قبل خمس سنوات، ونظراً لظروف الحياة لم أستطع حتى الآن تكملة أغراض الزواج، فهل في ذلك حرج، علماً بأن المخطوبة موافقة على هذا الانتظار، جزاكم الله خيراً؟","title":"حكم خطبة المرأة وتأخير الزواج بموافقة الطرفين","answer":"الجواب: لا حرج في هذا، ما دامت المخطوبة موافقة فلا حرج في ذلك، نسأل الله أن يسهل أمركما جميعاً. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8206/حكم-خطبة-المراة-وتاخير-الزواج-بموافقة-الطرفين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_301/30109.mp3","categories":["الخِطْبَة والاختيار ","نصائح وتوجيهات"]},{"id":10210,"question":"تسأل أختنا من جمهورية مصر العربية سؤالًا ثالث فتقول: شاب مؤمن ملتزم، خطب فتاة هي الأخرى ملتزمة، ولكن دون أن يراها، فهل هذه الخطبة صحيحة؟ وهل هذا الشاب يعد مخالفًا للسنة؟","title":"مشروعية رؤية الخاطب لمخطوبته دون خلوة","answer":"الجواب: كونه يراها أفضل، النبي ﷺ أمر بأن يراها إذا أمكن له ذلك، وقال لبعض الصحابة: اذهب فانظر إليها وقال: إذا خطب أحدكم امرأة فإن استطاع أن ينظر إلى ما يدعوه إلى نكاحها فليفعل فإن ذلك أقرب إلى أن يؤدم بينهما يعني: إلى أن يلتئم النكاح بينهما والحب بينهما، فالمقصود أنه إذا تيسر له النظر إليها فذلك مستحب وهو أقرب إلى الاجتماع والوئام وحصول المودة، ولهذا قال عليه الصلاة والسلام: إذا خطب أحدكم المرأة فإن استطاع أن ينظر منها إلى ما يدعوه إلى نكاحها فليفعل فإن ذلك أقرب إلى أن يؤدم بينهما أو كما قال عليه الصلاة والسلام، فأنت -يا عبد الله- يشرع لك أن تنظر إلى خطيبتك، فإذا تيسر ذلك برضا أهلها أو بطريقة أخرى، فإن لم يرضوا إذا كان ذلك على وجه ليس فيه خلوة ولا تعاطي ما حرم الله بأن يجلس لها في محل عند الجيران أو غيرهم حتى يراها على وجه يمكنه من الرغبة فيها أو عدم ذلك.\nقال جابر: إنه خطب امرأة فجعل يتخبأ لها بين النخل حتى رأى منها ما دعاه إلى نكاحها أو كما قال . فالمقصود أن رؤيته لها أمر مطلوب، وإذا تيسر باختيارها واختيار أهلها كان أكمل من دون خلوة، يزورهم ويرونه إياها بحضور أمها أو أبيها أو عمها أو نحو ذلك حتى لا تكون خلوة، وإن نظر إليها من جهة أخرى ليس فيها علمهم فلا بأس بذلك إذا كان على وجه ليس فيه محذور شرعًا. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8380/مشروعية-روية-الخاطب-لمخطوبته-دون-خلوة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_335/33503.mp3","categories":["الخِطْبَة والاختيار ","نصائح وتوجيهات"]},{"id":10526,"question":"يسأل ويقول سماحة الشيخ: ما هي الصفات التي ترونها في الزوجة الصالحة التي يريد أن يخطبها الرجل؟","title":"صفات الزوجة الصالحة","answer":"الجواب: الزوجة الصالحة هي المقيمة لأمر الله، المحافظة على الصلاة في أوقاتها، البعيدة عن التبرج في خروجها إلى الأسواق، المعروفة بحسن السمت والسيرة، هذه هي الزوجة الصالحة. فالتي تريد زواجها اسأل عنها؛ لقوله ﷺ: فاظفر بذات الدين تربت يداك، فإذا ذكرت لك بالمحافظة على الصلاة، والتستر وعدم التبرج، وعدم تعاطي الكذب وأشباه ذلك، فهذه هي المرأة الصالحة، الله ييسر أمرنا وأمرك. نعم.\nالمقدم: اللهم آمين جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/8701/صفات-الزوجة-الصالحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_283/28315.mp3","categories":["الخِطْبَة والاختيار ","نصائح وتوجيهات"]},{"id":10575,"question":"أختنا نادية من الجزائر تسأل عن الجلوس أمام الخاطب بحضرة الأهل هل يجوز هذا أو لا؟","title":"حكم الجلوس مع الخاطب بحضور محرم وتكرار الجلوس","answer":"الجواب: لا مانع أن تجلس أمام الخاطب حتى ينظر إليها من دون خلوة، يكون معها أبوها أو أخوها أو امرأة أو أمها أو نحو ذلك، ليس له الخلوة بها، والنبي ﷺ قال للخاطب: اذهب فانظر إليها، وقال عليه الصلاة والسلام: إذا خطب أحدكم امرأة فإن استطاع أن ينظر منها إلى ما يدعوه إلى نكاحها فليفعل.\nالمقصود: أنه إذا تيسر أن ينظر إليها فهو مناسب؛ لأن هذا أقرب إلى أن يؤدم بينهما، أقرب إلى أن تنجح الخطبة وأقرب إلى أن ينجح النكاح، لكن ليس له أن يخلو بها، بل يراها بحضور غيرها كأبيها ونحوه. نعم.\nالمقدم: جزاكم الله خيرا، تكرار الجلوس سماحة الشيخ، هي تسأل عن تكرار الجلوس؟\nالشيخ: إذا دعت الحاجة للتكرار لا بأس، كأن تكون المرة الأولى لم تكف أو الثانية، إذا دعت الحاجة لا حرج حتى تعرفه ويعرفها جيداً.\nالمقدم: أما باستمرار.\nالشيخ: أما باستمرار بدون حاجة ما ينبغي، لأن الأصل التحريم وإنما جاز للمصلحة والحاجة، ولأن التكرار الكثير بدون حاجة قد يفضي إلى فساد، قد يفضي إلى خلوة، وقد يفضي إلى زنا نسأل الله السلامة، نعم، كما قد وقع لكثير من الناس.\nالمقدم: نعم نعم، إذاً: الجلوس للحاجة فقط.\nالشيخ: والمصلحة التي تتعلق بالنكاح من دون خلوة.\nالمقدم: بارك الله فيكم، جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8742/حكم-الجلوس-مع-الخاطب-بحضور-محرم-وتكرار-الجلوس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_323/32302.mp3","categories":["الخِطْبَة والاختيار ","نصائح وتوجيهات"]},{"id":10620,"question":"رسالة وصلت إلى البرنامج من شقرا باعثها مستمع من هناك، رمز إلى اسمه بقوله: أبو مسلم ، أخونا يقول: لدي ابنة تقدم إليها أكثر من شخص، ولكن مشكلتي أن من يتقدم فيه إحدى هذه الأمور، أولاً: إما أنه لا يصلي فقط، أو أنه متساهل لا يرى في المسجد إلا نادراً، أو يشرب الدخان ويصلي، أو لا يشرب الدخان ولا يصلي، ولقد تعبت من لوم الناس لي بعدم تزويج ابنتي، وحجتهم: أن الله يهديهم بعد الزواج، ماذا ترون هل أرفضهم، أم أزوجهم لإبراء الذمة؟ وأي الأشخاص تنصحونني بتزويجه من هذه الأصناف التي ذكرت؟","title":"حكم تزويج من لا يصلي ومن يشرب الدخان","answer":"الجواب: من لا يصلي لا يزوج، لأن ترك الصلاة كفر أكبر، نسأل الله..، في أصح قولي العلماء، وإن كان لا يجحد وجوبها، فالصواب: أن تاركها كافر؛ لقوله ﷺ: بين الرجل وبين الكفر والشرك ترك الصلاة ، وقال عليه الصلاة والسلام: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر.\nفالذي لا يصلي أو لا يعرف في المساجد لا ينبغي أن يزوج، ولا يجوز أن يزوج بمسلمة.\nأما من كان يتعاطى الدخان، ولكنه يصلي فهذا يزوج، معصية لا تمنع من الزواج، وذلك أولى من تركها وتعطيلها، وهكذا لو كان عنده معصية أخرى، مثل يتساهل في بعض الأمور الأخرى التي لا تجعله كافراً، كأن تفوته بعض الجماعة وإلا هو يصلي معروف يصلي مع الناس ويقيم الصلاة لكن قد تفوته بعض الجماعة في بعض الأحيان، أو يعرف بشيء من المعاصي الأخرى مثل قص لحيته أو ما أشبه ذلك، هذا إذا لم يتيسر غيره فلا بأس ولا تعطل، فالمعصية لا تمنع الزواج، إنما يمنع الزواج الكفر، أما المعصية لا تمنع إذا رضيت البنت بذلك، وإذا تيسر السليم من المعاصي فذلك ينبغي طلبه والحرص عليه الله المستعان.\nالمقدم: الله المستعان جزاكم الله خيراً ونفع بعلمكم.","link":"https://binbaz.org.sa/fatwas/8797/حكم-تزويج-من-لا-يصلي-ومن-يشرب-الدخان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_327/32709.mp3","categories":["الخِطْبَة والاختيار ","نصائح وتوجيهات"]},{"id":10683,"question":"من تعز في الجمهورية العربية اليمنية المستمع محمد الأديمي بعث يسأل ويقول: ما هي آداب الخطوبة الإسلامية جزاكم الله خيراً؟","title":"آداب الخطوبة وضوابطها","answer":"الجواب: المستحب أن يرى المرأة إذا تيسر، هذا من الآداب، ومن أسباب التوفيق أن يجتهد في رؤيتها قبل أن يعقد عليها بالطرق الشرعية، إما بالاستئذان من أهلها حتى يراها، أو بأن يجلس في مجلس يمكن أن يراها ولو بغير إذنها، ولو بغير إذن أهلها أيضاً، فيكون في محل يمكنه أن يراها من دون علمها، من طريق جيرانها أو غير ذلك على وجه ليس فيه خلوة، إنما من بعيد إلى بعيد، وإن استأذنهم واجتمع بها ورآها وكلمها وكلمته فلا بأس؛ لأن الرسول ﷺ أمر الخاطب أن ينظر قال: إذا خطب أحدكم المرأة فإن استطاع أن ينظر منها إلى ما يدعوه إلى نكاحها فليفعل، وجاءه رجل ﷺ فذكر له أنه خطب امرأة، فقال: أنظرت إليها؟ قال: لا. قال: فاذهب فانظر إليها رواه مسلم .\nفالسنة أن ينظر إذا تيسر لكن من دون خلوة، بل بحضرة أبيها أو أخيها أو أمها، أو جماعات آخرين، المقصود لا يخلو بها، أو ينظرها من بعيد من دون علمها أو من دون علم أهلها لا بأس بذلك؛ لأن هذا من أسباب التوفيق إذا رآها واقتنع بها، فإن لم يتيسر ذلك شرع له أن يبعث إليها من ينظرها من النساء الثقات ويعطيه خبرها. نعم.\nالمقدم: جزاكم الله خيراً، إذاً تشترطون في كل الأحوال عدم الخلوة؟\nالشيخ: لابد من عدم الخلوة، لا تجوز الخلوة؛ لأنها حرام ولأنها من أسباب الفتنة أيضاً. نعم.\nالمقدم: وقد لا تتم الخطوبة؟\nالشيخ: نعم، وقد لا تتم الخطوبة.\nالمقدم: جزاكم الله خيراً، هل يمكن أن تمتد الخطوبة بين المخطوبين فترة طويلة إذا اتفقا؛ بسبب ظروف الدراسة مثلاً سنتين أو ثلاث سنوات؟\nالشيخ: لا، ليس لها حد، لا نعلم حداً في هذا، لكن بس ليس له أن يخلو بها ولا أن تركب معه ولا يسافر بها، بل يجب أن يكون كل واحد بعيد عن الآخر؛ حتى لا تقع الفتنة، إنما كلام من طريق الهاتف، أو الزيارة من طريق الجهر يعني: بين أهلها، يزورهم ويتصل بها ويتخبر أخبارها، لا بأس.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8859/اداب-الخطوبة-وضوابطها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_330/33009.mp3","categories":["الخِطْبَة والاختيار ","نصائح وتوجيهات"]},{"id":10688,"question":"من تعز في الجمهورية العربية اليمنية المستمع محمد الأديمي بعث يسأل ويقول: ما هي آداب الخطوبة الإسلامية جزاكم الله خيراً؟","title":"آداب الخطوبة وضوابطها","answer":"الجواب: المستحب أن يرى المرأة إذا تيسر، هذا من الآداب، ومن أسباب التوفيق أن يجتهد في رؤيتها قبل أن يعقد عليها بالطرق الشرعية، إما بالاستئذان من أهلها حتى يراها، أو بأن يجلس في مجلس يمكن أن يراها ولو بغير إذنها، ولو بغير إذن أهلها أيضاً، فيكون في محل يمكنه أن يراها من دون علمها، من طريق جيرانها أو غير ذلك على وجه ليس فيه خلوة، إنما من بعيد إلى بعيد، وإن استأذنهم واجتمع بها ورآها وكلمها وكلمته فلا بأس؛ لأن الرسول ﷺ أمر الخاطب أن ينظر قال: إذا خطب أحدكم المرأة فإن استطاع أن ينظر منها إلى ما يدعوه إلى نكاحها فليفعل، وجاءه رجل ﷺ فذكر له أنه خطب امرأة، فقال: أنظرت إليها؟ قال: لا. قال: فاذهب فانظر إليها رواه مسلم .\nفالسنة أن ينظر إذا تيسر لكن من دون خلوة، بل بحضرة أبيها أو أخيها أو أمها، أو جماعات آخرين، المقصود لا يخلو بها، أو ينظرها من بعيد من دون علمها أو من دون علم أهلها لا بأس بذلك؛ لأن هذا من أسباب التوفيق إذا رآها واقتنع بها، فإن لم يتيسر ذلك شرع له أن يبعث إليها من ينظرها من النساء الثقات ويعطيه خبرها. نعم.\nالمقدم: جزاكم الله خيراً، إذاً تشترطون في كل الأحوال عدم الخلوة؟\nالشيخ: لابد من عدم الخلوة، لا تجوز الخلوة؛ لأنها حرام ولأنها من أسباب الفتنة أيضاً. نعم.\nالمقدم: وقد لا تتم الخطوبة؟\nالشيخ: نعم، وقد لا تتم الخطوبة.\nالمقدم: جزاكم الله خيراً، هل يمكن أن تمتد الخطوبة بين المخطوبين فترة طويلة إذا اتفقا؛ بسبب ظروف الدراسة مثلاً سنتين أو ثلاث سنوات؟\nالشيخ: لا، ليس لها حد، لا نعلم حداً في هذا، لكن بس ليس له أن يخلو بها ولا أن تركب معه ولا يسافر بها، بل يجب أن يكون كل واحد بعيد عن الآخر؛ حتى لا تقع الفتنة، إنما كلام من طريق الهاتف، أو الزيارة من طريق الجهر يعني: بين أهلها، يزورهم ويتصل بها ويتخبر أخبارها، لا بأس.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8859/اداب-الخطوبة-وضوابطها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_330/33009.mp3","categories":["الخِطْبَة والاختيار ","نصائح وتوجيهات"]},{"id":10692,"question":"إذا كانت المخطوبة لا تصلي، وقام الخطيب بتعليمها الصلاة أثناء فترة الخطوبة، واشترط عليها أن تصلي، وكانت من أهم الشروط، فما حكم الشرع في ذلك، جزاكم الله خيراً؟","title":"حكم تعليم الخطيب لمخطوبته الصلاة","answer":"الجواب: هذا من أهم الأمور كونه يعلمها الصلاة ويدعوها إليها هذا من أبرك ما يكون وهو واجب، ليس له أن يتزوجها وهي لا تصلي إذا كان مسلماً، ليس له أن يتزوجها حتى تصلي، تلتزم بالصلاة تتوب، وهي كذلك ليس لها أن تزوج رجلاً لا يصلي، لابد أن يكون مصلياً مستقيماً، فالمرأة تحرص على أن يكون زوجها وخطيبها يصلي وهو كذلك يحرص، حتى يكونا جميعاً مصليين مسلمين، وكثير من الناس اليوم يتساهل في هذا، فربما كان الزوج لا يصلي وهي تصلي، وربما كان العكس، هي لا تصلي وهو يصلي، فالواجب الحذر، والواجب أن لا يتزوج امرأة لا تصلي، والواجب عليها هي أن لا تزوج رجلاً لا يصلي، بل يجب الحذر من ذلك؛ لقول النبي ﷺ: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر، فالأمر عظيم، وقال عليه الصلاة والسلام: بين الرجل وبين الكفر والشرك ترك الصلاة، وقال عليه الصلاة والسلام: رأس الأمر الإسلام، وعموده الصلاة.\nفالحاصل أن الصلاة عمود الإسلام، فلابد أن يكون الرجل يصلي وهي تصلي، إذا كانا منتسبين للإسلام لابد من هذا، أما إذا كانا كفار فالمسألة ثانية، يجوز لليهودي أن ينكح اليهودية، والنصراني النصرانية، والكافر ينكح الكافرة، لكن ماداما منتسبين للإسلام فلابد من الصلاة، فإذا تزوج أحدهما الآخر وهو لا يصلي لم يصح النكاح، بل لابد أن يكونا جميعاً مصليين يصليان أو لا يصليان، يكونان مشتركين في الصلاة أو في عدمها، أما إذا كان أحدهما يصلي والآخر لا يصلي، فإنه لا يصح النكاح في أصح قولي العلماء؛ لأن ترك الصلاة كفر أكبر، وإن كان لم يجحد وجوبها. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8860/حكم-تعليم-الخطيب-لمخطوبته-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_330/33010.mp3","categories":["الخِطْبَة والاختيار ","نصائح وتوجيهات"]},{"id":10972,"question":"من القصيم وردتنا هذه الرسالة بها مجموعة من الأسئلة السائل: (أ. ص. ع). القصيم يقول: سماحة الشيخ: ما حكم نظر المخطوب إلى مخطوبته وهي بكامل زينتها، ودون حجاب على رأسها، نرجو من سماحة الشيخ التوجيه؟","title":"حكم نظر الخاطب إلى مخطوبته وهي بكامل زينتها","answer":"الجواب:  لا بأس بذلك، النبي ﷺ أمر بالنظر إلى المخطوبة، فالسنة للخاطب أن ينظر إليها، وإلى وجهها وشعرها ويديها وقدميها، كل هذا لا بأس به، لكن من غير خلوة، ينظر إليها من دون خلوة بها.. بحضور أبيها، أو أمها، أو غيرهما، أو من بعيد من فرجة، أو من جدار، أو من شبه ذلك لا بأس، أما الخلوة بها في محل واحد لا، لا يجوز، لكن إذا اجتمع بها مع أمها، أو مع أختها، أو مع عمتها، أو مع غيرهم فلا حرج في ذلك، بل هو مستحب، وله أن ينظر؛ لأن هذا من أسباب التوفيق ومن أسباب أن يؤدم بينهما.","link":"https://binbaz.org.sa/fatwas/9150/حكم-نظر-الخاطب-الى-مخطوبته-وهي-بكامل-زينتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_286/28616.mp3","categories":["الخِطْبَة والاختيار ","نصائح وتوجيهات"]},{"id":11282,"question":"يسأل سؤالًا آخر فيقول: أريد الزواج من إحدى الأسر، لكن جدي منع أولاده وبناته من الزواج من هؤلاء بحجة وجود خلافات قديمة، ما حكم الشرع في ذلك؟","title":"حكم طاعة الجد في عدم الزواج من أسرة معينة","answer":"الجواب:  الأولى لك أن تدعهم لأن الجد أب وبره مطلوب، ولعل في ذلك خيرًا للجميع، فالناس كثير والنساء كثير والحمد لله. فالمشروع لك والأفضل لك فيما أرى التماس جماعة آخرين غير الجماعة التي لا يرضاها جدك لأسباب أشرت إليها، أما تحريم ذلك فهو محل نظر، لكن كونك تتركهم وتراعي خاطر جدك لأنه أب، الجد أب والبر واجب، ولعل في تركهم مصلحة بينة للجميع، هذا لعله أحوط وأولى إن شاء الله. نعم. المقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9451/حكم-طاعة-الجد-في-عدم-الزواج-من-اسرة-معينة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_375/37502.mp3","categories":["الخِطْبَة والاختيار ","بر الوالدين"]},{"id":11430,"question":"المستمع (س. ع) بعث يسأل ويقول: عندما يريد إنسان خطبة فتاة في الشرع يباح أن ينظر إلى وجهها، و تستمر فترة الخطوبة أحيانًا شهرًا، وشهرين، وسنة، هل يجوز لها في هذه الفترة أن تكشف الوجه والأيدي، أم تستر وجهها، وأيديها حتى يتم الدخول بها؟ جزاكم الله خيرًا.","title":"حكم النظر إلى المخطوبة بين فترة وأخرى","answer":"الجواب:  لا حرج على الخاطب في النظر إلى مخطوبته، ولا حرج عليها في النظر إليه، حتى يطمئن كلًا منهما للآخر، فإذا اطمأن كلًا منهما؛ كفى، والحمد لله. المقصود أن الخاطب له النظر؛ ليزداد رغبة، أو يعرف أشياء يريدها حتى يرجع عن الخطبة إذا كان يخشى شيئًا.  المقصود أن النظر لا بأس به من دون خلوة، حتى يطمئن، وتطمئن إلى الرغبة، أو عدمها، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9612/حكم-النظر-الى-المخطوبة-بين-فترة-واخرى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_294/29406.mp3","categories":["الخِطْبَة والاختيار ","نصائح وتوجيهات"]},{"id":11437,"question":"المستمع صالح عبدالرحمن من الرياض، بعث يسأل ويقول: ما هي مواصفات المرأة التي يقدم المسلم على الاقتران بها؟","title":"مواصفات المرأة التي يقدم المسلم على الزواج بها","answer":"الجواب:  يقول النبي ﷺ في الحديث الصحيح: تنكح المرأة لأربع: لمالها، ولجمالها، ولحسبها، ولدينها؛ فاظفر بذات الدين تربت يداك  فليكن همك الوحيد هو صلاح دينها، فإذا كان مع ذلك جمال ومال وحسب؛ فهذا خير إلى خير، طيب، لكن لا يكون همك الجمال، أو المال، أو الحسب، لا. فليكن أكبر الهم، وأعظم القصد صلاح الدين، واستقامة الأخلاق، تسأل عنها الخبيرين بها، فإذا كانت ذات دين، بعيدة عن التبرج، وعن أسباب الفتنة، محافظة على الصلاة في أوقاتها؛ فاقرب منها، وإذا كانت بخلاف ذلك؛ فاتركها، المهم أن العناية الكبرى تكون بالدين، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9619/مواصفات-المراة-التي-يقدم-المسلم-على-الزواج-بها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_294/29413.mp3","categories":["الخِطْبَة والاختيار ","نصائح وتوجيهات"]},{"id":11805,"question":"يقول: لي صديق كان يخطب امرأة من مدة عامين، وكان هو في الخارج يعمل، وعندما قدم من الخارج قال لوالد العروسة: إن شاء سوف نكتب الكتاب، فرفض والد العروسة، وقال: نعمل شبكة -يعني حلي- وبعد عام نكتب الكتاب، فرفض صديقي هذا، وقام بفك الخطوبة،  هل -يا سماحة الشيخ- صديقي عليه إثم؟ وهل هو ظلم تلك المرأة؟ أفيدونا عن هذه القضية جزاكم الله خيرًا.","title":"حكم من فسخ الخطوبة لتأخير والد المخطوبة موعد الزواج","answer":"الجواب:  لا حرج في ذلك أن يدع الخطوبة، مادام والدها لم يبادر بالتزويج؛ فلا حرج على الخاطب أن يدع الخطوبة، وإن أحب أن يصبر؛ فلا بأس، المقصود لا يلزمه الصبر إن عجلوا له الزواج؛ فالحمد لله، وإلا فله أن يدع هذه البنت، ويلتمس غيرها؛ لأن المدة طويلة، حتى ولو كان المدة قصيرة مادام لم يتزوج؛ فهو حر إن شاء استمر في الخطبة وتزوج، وإن شاء ترك، ولو قبل ذلك بيوم أو يومين، لا حرج عليه. المقصود: أن الخطبة لا تلزمه، متى شاء تحويله عن المرأة، وهي كذلك إذا أحبت أن ترغب عنه؛ فلا بأس، مادام العقد لم يتم، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9989/حكم-من-فسخ-الخطوبة-لتاخير-والد-المخطوبة-موعد-الزواج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_423/42307.mp3","categories":["الخِطْبَة والاختيار ","نصائح وتوجيهات"]},{"id":11867,"question":"درج النساء على لبس ما يسمى دبلة الخطوبة، فما هو توجيه سماحتكم؟","title":"حكم لبس دبلة الخطوبة","answer":"الجواب:  لا أعلم لها أصلًا، فإن كانت من عمل الكفار فالذي ينبغي تركها، وإن كانت ليست عملًا للكفار، بل اعتادها الناس؛ فالأمر فيها واسع سهل، لكن تركها أفضل بكل حال. نعم. المقدم: جزاكم الله خيرًا. نعم.","link":"https://binbaz.org.sa/fatwas/10045/حكم-لبس-دبلة-الخطوبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_397/39708.mp3","categories":["الأخلاق المذمومة","اللباس والزينة","الخِطْبَة والاختيار "]},{"id":12295,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من اليمن الجنوبي، وباعثة الرسالة إحدى الأخوات من هناك تقول: أم أيمن، أم أيمن عرضنا لها أربعة أسئلة في حلقة مضت، وفي هذه الحلقة لها جمع من الأسئلة، فتقول في أحدها: إنني فتاة ملتزمة بتعاليم ديني، والحمد لله، ولا أريد أن أتزوج إلا من شاب ملتزم مجاهد بنفسه، ومجاهد بماله في سبيل الله، ولكن أهل القرية التي أعيش فيها يصلون، ويصومون فقط، ويتغاضون عن بعض التعاليم الإسلامية، ولا أنكر إيمانهم، فإن الله عليم بذات الصدور، وسؤالي هو: هل أتزوج على أي شاب من هؤلاء إذا تقدم إلي، أم أرفضهم؛ لأنهم قاعدون عن الجهاد بالنفس، علمًا بأن ظروفي الأسرية قاسية، وكذا ظروفي المادية، وأنا لا أريد الخروج إلى العمل؛ لأن جميع مرافق العمل تعاني من ميكروب الاختلاط الفتاك، خذوا بيدي إلى طريق الخير والرشاد، جزاكم الله خيرًا؟","title":"الوصية بتحري الرجل الذي ظاهره الاستقامة لمن أرادت الزواج","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه. نصيحتي لك أيها السائلة، أن تزوجي بمن ظاهره الإسلام والاستقامة، ما دام يصلي وظاهره الإسلام، ولم تعلمي عنه ما يوجب كفره بالله؛ فتزوجي، ونسأل الله أن يصلح أحوال المسلمين، وأن يوفق الدولة لديك للالتزام بالإسلام والدعوة إليه، ونبذ ما خالف الإسلام. وأنت اجتهدي في التماس الرجل الصالح، واسألي عنه أنت وأولياؤك، اسألي عنه أهل الخير، فإذا كان ملتزمًا بالصلاة، مستقيمًا في دينه؛ فلا بأس أن تتزوجي عليه، وإن كان ليس بكامل، وإن كان عنده بعض النقص في بعض المعاصي والسيئات، ما دام مسلمًا لا يدعو القبور، ولا يستغيث بالأموات، وليس شيوعيًا، وإنما هو مسلم لا يرضى بـالشيوعية ولا يعتقدها ولا يوالي أهلها، بل هو مصل صائم مستقيم، فلا بأس عليك ... بتزوجه وإن كان عنده شيء من النقص، كأخذ بعض لحيته، أو تدخين، أو ما أشبه هذا من المعاصي التي تقع من بعض الناس، ولا تجلسي هكذا بدون زوج، ونسأل الله أن يسهل لك الرجل الصالح، وأن يصلح أحوال الجميع، وأن يهدي الدولة، ويوفقها لما فيه رضاه، وأن يهديها حتى تدع ما يخالف الشرع المطهر، وحتى تستقيم على دين الله الذي به سعادتها ونجاتها، وسعادة شعبها ونجاة شعبها، نسأل الله للجميع الهداية. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10495/الوصية-بتحري-الرجل-الذي-ظاهره-الاستقامة-لمن-ارادت-الزواج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_453/45301.mp3","categories":["الخِطْبَة والاختيار ","نصائح وتوجيهات"]},{"id":12980,"question":"هذا السائل من الرياض أبو محمد ( أ . أ ) يقول: إذا خطب مني الشخص ابنتي وقيل لي: بأن هذا الخاطب محافظ على الصلوات تمامًا في جميع أوقاتها، فهل أكتفي بهذا في قبوله زوجًا، أم أن هناك أمورًا أخرى أسأل عنها مثل: شرب الدخان، سفره، أصحابه، وغير ذلك؟","title":"الاحتياط في السؤال عن دين الخاطب وأخلاقه وجلسائه","answer":"الجواب:  الاحتياط السؤال الكامل عن سيرته وأعماله وجلسائه حتى تكون على بينة، وإلا فالمحافظة على الصلوات علامة خير، لكن قد يكون هناك عنده أشياء أخرى، فإذا سألت عنه سؤالًا تامًا؛ كان ذلك أكمل، وأفضل احتياطًا للأمانة التي عندك لهذه البنت، أو الأخت، أو نحوها؛ لأنها أمانة. فالواجب عليك أن تحتاط لها، ولا سيما في هذا العصر الذي اختلط فيه الحابل بالنابل، واختلط فيه المسلم بالكفار، والعصاة بالأبرار، فالواجب على الولي أن يحتاط؛ ولهذا قال ﷺ: إذا خطب إليكم من ترضون دينه وخلقه؛ فزوجوه إلا تفعلوه؛ تكن فتنة في الأرض، وفساد كبير كيف يمكنك أن ترضى دينه وخلقه وأنت ما سألت عنه الأخيار الطيبين؟! مجرد حضوره للصلاة ما يكفي، وإن كان ذلك علامة خير، وعلامة هدى، ولكن الاحتياط أن تسأل عن سيرته أيضًا ........ المقدم: شكر الله لكم -يا سماحة الشيخ- وبارك الله فيكم، وفي علمكم، ونفع بكم المسلمين.","link":"https://binbaz.org.sa/fatwas/11197/الاحتياط-في-السوال-عن-دين-الخاطب-واخلاقه-وجلساىه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_503/50310.mp3","categories":["الخِطْبَة والاختيار ","نصائح وتوجيهات"]},{"id":12982,"question":"تسأل أيضًا وتقول: كيف تختار المرأة المسلمة المحجبة المؤمنة بالله شريك الحياة؟ وما هي صفاته؟ بينوها لنا مأجورين؟ جزاكم الله خيرًا.","title":"صفات الزوج الصالح","answer":"الجواب:  تلتمس الرجل الطيب المعروف بالخير المحافظ على الصلوات، صاحب العقيدة الطيبة، تسأل عنه من يعرفه من الثقات الذين تعرفهم إذا خطبها، ولو تخطبه هي لا بأس، إذا عرفته بالخير والاستقامة، وأوصت عليه وليها، أو غير وليها أنها توافق على خطبته لها؛ فلا بأس، فقد أهدت امرأة نفسها للنبي ﷺ وأقرها على ذلك -عليه الصلاة والسلام- ولما لم يرغب فيها زوجها غيره -عليه الصلاة والسلام- وعمر  عرض ابنته حفصة على الصديق ، وعلى عثمان بعدما تأيمت من زوجها، ثم تزوجها النبي ﷺ. فالمقصود: أن المرأة لا مانع أن تختار لنفسها الرجل الطيب المعروف بالاستقامة في دينه، ولكن لا تبت في ذلك إلا بطريق وليها، وليها هو الذي يزوجها، فإذا اتفقت مع وليها على رجل طيب؛ هذا هو المطلوب، وليس لوليها أن يجبرها على شخص ليس بطيب، أو على شخص لا ترضاه، وليس لها هي أن تختار شخصًا يضر أولياءها، ويسبب المشاكل بينها وبين أوليائها، عليها أن تسلك المسالك الحسنة، وأن تختار الطيب الذي ليس في اختياره مشاكل ولا مضرة على أوليائها، نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11199/صفات-الزوج-الصالح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_470/47011.mp3","categories":["الخِطْبَة والاختيار ","نصائح وتوجيهات"]},{"id":13211,"question":"السائل من جمهورية مصر العربية، والذي رمز لاسمه بـ (س. م) يعمل بالرياض يقول في هذا  ما حكم الشرع في نظركم في مراسلة الخطيب لخطيبته، والعكس مع ملاحظة ذلك بأن عدم المراسلة قد يسبب للخطيبة تعبًا نفسيًا، وأضرارًا صحية ودراسية، وجهونا في ضوء هذا السؤال؟","title":"حكم مراسلة الخطيب خطيبته والعكس","answer":"الجواب:  لا أعلم بأسًا في ذلك أن يخاطبها، وتخاطبه بالتلفون، أو بالمكاتبة لتأكيد الخطبة أو للسؤال عن بعض المهمات التي ليس فيها وسيلة إلى الاجتماع المحرم قبل الزواج، إنما سؤال عن كذا أو كذا، تسأله وهو يسألها عن أمور تتعلق بالزواج، وبمصلحة الزواج، ولا يخشى منها فتنة، فلا حرج في ذلك من طريق الكتابة، أو من طريق المهاتفة التلفون. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11485/حكم-مراسلة-الخطيب-خطيبته-والعكس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_512/51214.mp3","categories":["الخِطْبَة والاختيار ","نصائح وتوجيهات"]},{"id":13313,"question":"السائل رأفت علي يقول في هذا  إنني قد تقدمت لخطبة ابنة عمي، وجاءت الموافقة -والحمد لله- والآن قد مضى على الخطوبة ما يقرب من سنة، ولكن والدتي غير راضية عن هذه الخطوبة من ابنة عمي، وأنا أعرف بأن هذه البنت تصلي، وتقوم بالأمور الشرعية، وملتزمة بالحجاب الشرعي، وتقوم بالليل، وأنا الآن في حيرة من إحراج عمي، وفي حيرة أخرى من ناحية والدي، ومحتار، فما هو الحل في نظركم سماحة الشيخ؟","title":"مراعاة رأي الأم في اختيار الزوجة","answer":"الجواب: الواجب على والدتك أن تتقي الله، وأن لا تمنعك من هذا الزواج الذي ينفعك ولا يضرك ما دامت البنت على ما ذكرت، فالواجب على الوالدة الموافقة، لكن إذا وجدت ابنة تناسب الوالدة، وهي أيضًا تناسبك من جهة دينها، وخلقها وخلقها؛ فلا بأس إذا جمعت بين المصلحتين، إذا تيسر بنت ترضاها، وترضاها الوالدة؛ فهذا خير؛ لأن بر الوالدة مهم، ومراعاة خاطرها مهم، فإذا تيسرت لك زوجة غير هذه ترضاها الوالدة؛ فاحرص على ذلك. أما إذا لم يتيسر ذلك؛ فليس لها أن تمنعك، ولك أن تتزوج وإن لم ترض؛ لأن الرسول ﷺ قال: إنما الطاعة في المعروف وزواجك معروف فيه خير كثير، ومصالح جمة إذا كانت الزوجة صالحة، والحمد لله، وعليك أن ترضي الوالدة بالكلام الطيب، والأسلوب الحسن حسب الطاقة، لكن إن تيسرت امرأة ترضاها أنت، وترضاها الوالدة فهذا أكمل، وأطيب.","link":"https://binbaz.org.sa/fatwas/11599/مراعاة-راي-الام-في-اختيار-الزوجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_521/52105.mp3","categories":["الخِطْبَة والاختيار ","بر الوالدين"]},{"id":13367,"question":"سماحة الشيخ عبدالعزيز! حفظكم الله، لعل لكم توجيه في رؤية الخاطب لمخطوبته، وما هو المشروع في ذلك؟","title":"توجيه في رؤية الخاطب لمخطوبته","answer":"الجواب: سنة، رؤية الخاطب للمخطوبة سنة، النبي ﷺ قال للرجل الذي سأله قال: أنظرت إليها؟ قال: لا. قال: اذهب فانظر إليها وقال ﷺ: إذا خطب أحدكم المرأة، فإن استطاع أن ينظر منها إلى ما يدعوه إلى نكاحها؛ فليفعل هو سنة؛ لأنه يعين على الرغبة، أو عدمها. فالسنة للمؤمن إذا أراد أن يتزوج أن يرى، يجتهد، ويستأذن لعلهم يسمحون له بالرؤية، أو يراها، ولو ما دروا، إذا كان في محل يمكن يراها في... من دون خلوة، أو في عند جيرانها، أو ما أشبه ذلك، ينظرها، لكن من دون خلوة، بحضور أبيها، أو أمها، أو أخيها، أو غيرهم، أو ينظرها من بعيد من الفرجة، أو مع باب، أو ما أشبه ذلك... يقول جابر -رضي الله عنه- لما أراد أن يخطب امرأة قال: \"تخبأت لها حتى رأيت منها ما دعاني إلى نكاحها\". فالمقصود: أنه يفعل ما يستطيع، إن استطاع أن يستأذن منهم من أبيها، أو جدها، أو أخيها حتى يراها؛ فلا بأس، هذا أكمل، وإن لم يتيسر ذلك؛ سأل العارفين بها، حتى كأنه يراها، سألهم واستفصل، وإن رآها من دون أن يعلموا من فوة باب، أو عند جيران؛ فلا حرج، لكن من دون خلوة. نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11654/توجيه-في-روية-الخاطب-لمخطوبته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_515/51503.mp3","categories":["قضايا المرأة","الخِطْبَة والاختيار "]},{"id":13593,"question":"السائلة في هذه الرسالة تذكر بأنها فتاة ملتزمة لديها ابنة خالة في بيت واحد، هذه البنت تعمل أعمالًا كثيرة من الأخطاء، والتي لا ترضي الله  ولا ترضيني، تقول: إنها تهاتف رجلًا في الهاتف، وتؤخر الصلاة، وأيضًا تقول: قمت بنصحها، وتكلمت معها، ولكن لم ينفع معها النصح والتذكير، تقول: ومن ضمن هذا الهاتف بأن أحد الأشخاص وعدها بالزواج كباقي القصص التي نقوم بسماعها، هل يجوز لي أن أقوم بكشفها، وفضحها أمام أهلها؟ أم أستر عليها؟ وجهونا سماحة الشيخ.","title":"توجيه لمن ترى قريبتها تكلم الرجال عبر الهاتف","answer":"الجواب: الواجب نصيحتها، والستر عليها، تنصح توجه إلى الخير، وأن المهاتفة إذا كانت قد تفضي إلى الزنا؛ لا يجوز، أما المهاتفة بأنها تسأل عن حاله الذي يخطبها، ويسألها عن حالها لأجل الخطبة؛ فلا بأس، أما مهاتفة يخشى من ورائها أن يجتمعا على الفاحشة؛ فهذا لا يجوز. يجب أن تنصح، وتحذر من هذا الأمر المنكر، ولا مانع من وعيدها، وتخويفها بأنه يرفع بأمرها إلى أهلها؛ لعلها تستجيب، ولعلها تخاف، من باب الترهيب، والستر مطلوب لقول النبي ﷺ: من ستر مسلمًا؛ ستره الله في الدنيا والآخرة فهي يستر عليها، وتحذر، وأن الواجب عليها الكف عن هذا الشيء إلا إذا كان الرجل خاطبًا، أو يريد أن يخطب، ويتحدثا في موضوع الخطبة فقط؛ فلا حرج في ذلك. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11917/توجيه-لمن-ترى-قريبتها-تكلم-الرجال-عبر-الهاتف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_523/52303.mp3","categories":["الخِطْبَة والاختيار ","قضايا المرأة"]},{"id":13697,"question":"هذا السائل مصري خالد محمد ومقيم بتبوك، يقول في هذا  ما حكم الشرع في نظركم -سماحة الشيخ- في شاب خطب فتاة، واستمرت الخطوبة ما يقارب من عامين، ولكن الشاب ابتعد عنها لأسباب عائلية، ما حكم ذلك مأجورين؟","title":"حكم فسخ الخطبة","answer":"الجواب: لا حرج في ذلك، إذا خطب، ثم بدا له أن لا يتزوج له حق، سواء بعد سنة، أو أقل، أو أكثر، إذا خطبها ثم بدا له ألا يتزوجها، أو هي وافقت، ثم رجعت؛ لا حرج في ذلك، الحمد لله، ما دام ما تم العقد كل بالخيار، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12079/حكم-فسخ-الخطبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_535/53507.mp3","categories":["الخِطْبَة والاختيار ","نصائح وتوجيهات"]},{"id":13699,"question":"هذا السائل مصري خالد محمد ومقيم بتبوك، يقول في هذا  ما حكم الشرع في نظركم -سماحة الشيخ- في شاب خطب فتاة، واستمرت الخطوبة ما يقارب من عامين، ولكن الشاب ابتعد عنها لأسباب عائلية، ما حكم ذلك مأجورين؟","title":"حكم فسخ الخطبة","answer":"الجواب: لا حرج في ذلك، إذا خطب، ثم بدا له أن لا يتزوج له حق، سواء بعد سنة، أو أقل، أو أكثر، إذا خطبها ثم بدا له ألا يتزوجها، أو هي وافقت، ثم رجعت؛ لا حرج في ذلك، الحمد لله، ما دام ما تم العقد كل بالخيار، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12079/حكم-فسخ-الخطبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_535/53507.mp3","categories":["الخِطْبَة والاختيار ","نصائح وتوجيهات"]},{"id":14049,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من المستمع أحمد محمد علي سوداني وعمره خمس وعشرون سنة وعنوانه في العراق، أخونا له بعض الأسئلة، فيسأل في أحد أسئلته عن حكم تزوج الرجل المسلم بامرأة مسيحية، ويرجو التفصيل من سماحة الشيخ.","title":"حكم زواج المسلم بالمسيحية","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فقد بين الله  في كتابه الكريم في سورة المائدة حل الزواج من محصنات أهل الكتاب، كما قال جل وعلا في كتابه العظيم: الْيَوْمَ أُحِلَّ لَكُمُ الطَّيِّبَاتُ وَطَعَامُ الَّذِينَ أُوتُوا الْكِتَابَ حِلٌّ لَكُمْ وَطَعَامُكُمْ حِلٌّ لَهُمْ وَالْمُحْصَنَاتُ مِنَ الْمُؤْمِنَاتِ وَالْمُحْصَنَاتُ مِنَ الَّذِينَ أُوتُوا الْكِتَابَ مِنْ قَبْلِكُمْ إِذَا آتَيْتُمُوهُنَّ أُجُورَهُنَّ مُحْصِنِينَ غَيْرَ مُسَافِحِينَ وَلا مُتَّخِذِي أَخْدَانٍ[المائدة:5].  فأباح سبحانه المحصنات من أهل الكتاب وهم اليهود والنصارى، والمحصنة: هي العفيفة، الحرة العفيفة هي المحصنة، فإذا كانت معروفة بالعفة والبعد عن الفواحش فإنه يجوز للمسلم نكاحها، أما إذا كانت لا تعرف بذلك فلا يحل نكاحها، أو معروفة بالفحش والفساد فلا يجوز نكاحها، وإن كانت كافرة لكنها مستثناة، المحصنة من اليهود والنصارى مستثناة من المسلمين إذا كانت محصنة، والمحصنة - كما تقدم - الحرة العفيفة التي لا يعرف عنها تعاطي الفواحش يعني: الزنا، فهي محصنة عفيفة بعيدة عن تعاطي الفواحش وإن كانت على دينها على دين النصرانية، ولكن نكاح المسلمات أولى وأفضل وأحق وأحسن وأبعد عن الشر ولاسيما المسلمات المعروفات بالديانة والاستقامة فإن زواجهن أفضل بكثير وأولى بكثير وأبعد عن الخطر.\nفنصيحتي لإخواني جميعًا الحرص على الزواج من المسلمات الطيبات وعدم الزواج من المحصنات من أهل الكتاب؛ لأن في ذلك خطرًا من جهة تنصير أولاده ومن جهة عدم عفتها أيضًا ولو تظاهرت بخلاف ذلك، نسأل الله للجميع العافية والسلامة. نعم.\nالمقدم: اللهم آمين، جزاكم الله خيرًا، سماحة الشيخ في حالة وقوع ذلك بم تنصحون الزوج؟\nالشيخ: إذا كانت محصنة ولا رأى منها إلا الخير فلا بأس بذلك، فلا بأس ببقائها، وأما إن شك فيها أو رأى منها ما يريبه فينبغي له طلاقها.\nكذلك إذا تيسرت له امرأة صالحة مسلمة فإن الأولى والأحق به أن يتزوجها ويطلق تلك حرصًا على سلامة دينه ودين أولاده، فإن الأولاد على خطر من ذهابهم مع أمهم عند أقل خلاف أو عند موت الزوج أو عند الفرقة بينه وبينها فالخطر قائم، ولا حول ولا قوة إلا بالله.\nالمقدم: الله المستعان، جزاكم الله خيرًا، كأن الحدود ضيقة في إباحة الزواج بغير .... ؟\nالشيخ: نعم نعم، ولهذا كره بعض الصحابة ذلك، كان عمر يكره ذلك ويرغب الصحابة في ترك ذلك رضي الله عن الجميع. نعم.\nالمقدم: بارك الله فيكم، وجزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12479/حكم-زواج-المسلم-بالمسيحية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_613/61301.mp3","categories":["نصائح وتوجيهات","الخِطْبَة والاختيار ","نكاح الكفار"]},{"id":14117,"question":"أخونا له سؤال آخر مفهومه: أنه يعلم أن طاعة الوالدين واجبة، فيقول مثلًا: إن والده خطب له إحدى الفتيات لكنه علم أنها لا تصلي، فإذا ما رفض هذه المخطوبة هل يكون هذا من العقوق أو لا يا شيخ عبد العزيز؟","title":"حكم مخالفة الوالدين في خطبة فتاة لا تصلي؟","answer":"الجواب: ليس هذا من العقوق ولا يجوز نكاح امرأة لا تصلي؛ لأن ترك الصلاة كفر أكبر على الصحيح، لقول النبي ﷺ: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر، ولأنها عمود الإسلام، وذهب جمع من أهل العلم إلى أنه كفر أصغر، وإلى أنها معصية، وأنها لا تكفر بذلك، ولا يكفر الرجل بذلك إذا كان يقر بالوجوب ويعلم أنها واجبة، وبكل حال فالتي لا تصلي لا تنكح حتى ولو قلنا بعدم كفرها، لا ينبغي أن تنكح ولا يطاع الوالد فيها ولا الوالدة ولا غيرهما، يقول النبي ﷺ: إنما الطاعة في المعروف، لا طاعة لمخلوق في معصية الخالق. مع أن الصواب أن من ترك الصلاة يعتبر كافرًا وإن كان تركها تهاونًا، أما إذا جحد وجوبها فهذا كافر عند جميع أهل العلم نسأل الله العافية، وهكذا لو جحد وجوب الزكاة أو وجوب الصيام أو جحد وجوب الحج مع الاستطاعة يكون كافرًا عند أهل العلم. فينبغي للمؤمن أن يتحرى في الزواج المرأة الصالحة الطيبة كما قال النبي ﷺ في الحديث الصحيح: تنكح المرأة لأربع: لمالها ولجمالها ولحسبها ولدينها فاظفر بذات الدين تربت يداك، فالرجل يطلب المرأة الصالحة، وهكذا المرأة تطلب الرجل الصالح الطيب، لا تنكحي الذي لا يصلي أو يشرب الخمر أو .. تجتنبه، تلتمس الطيب، فهكذا الرجل يطلب المرأة الصالحة المعروفة بالدين والاستقامة والمحافظة على الصلاة حتى تستقيم العشرة بينهما على خير وهدى، وهكذا حتى تكون الذرية إن شاء الله كذلك صالحة. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12561/حكم-مخالفة-الوالدين-في-خطبة-فتاة-لا-تصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_615/61502.mp3","categories":["حكم الصلاة وأهميتها","الخِطْبَة والاختيار "]},{"id":14121,"question":"أخونا له سؤال آخر مفهومه: أنه يعلم أن طاعة الوالدين واجبة، فيقول مثلًا: إن والده خطب له إحدى الفتيات لكنه علم أنها لا تصلي، فإذا ما رفض هذه المخطوبة هل يكون هذا من العقوق أو لا يا شيخ عبد العزيز؟","title":"حكم مخالفة الوالدين في خطبة فتاة لا تصلي؟","answer":"الجواب: ليس هذا من العقوق ولا يجوز نكاح امرأة لا تصلي؛ لأن ترك الصلاة كفر أكبر على الصحيح، لقول النبي ﷺ: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر، ولأنها عمود الإسلام، وذهب جمع من أهل العلم إلى أنه كفر أصغر، وإلى أنها معصية، وأنها لا تكفر بذلك، ولا يكفر الرجل بذلك إذا كان يقر بالوجوب ويعلم أنها واجبة، وبكل حال فالتي لا تصلي لا تنكح حتى ولو قلنا بعدم كفرها، لا ينبغي أن تنكح ولا يطاع الوالد فيها ولا الوالدة ولا غيرهما، يقول النبي ﷺ: إنما الطاعة في المعروف، لا طاعة لمخلوق في معصية الخالق. مع أن الصواب أن من ترك الصلاة يعتبر كافرًا وإن كان تركها تهاونًا، أما إذا جحد وجوبها فهذا كافر عند جميع أهل العلم نسأل الله العافية، وهكذا لو جحد وجوب الزكاة أو وجوب الصيام أو جحد وجوب الحج مع الاستطاعة يكون كافرًا عند أهل العلم. فينبغي للمؤمن أن يتحرى في الزواج المرأة الصالحة الطيبة كما قال النبي ﷺ في الحديث الصحيح: تنكح المرأة لأربع: لمالها ولجمالها ولحسبها ولدينها فاظفر بذات الدين تربت يداك، فالرجل يطلب المرأة الصالحة، وهكذا المرأة تطلب الرجل الصالح الطيب، لا تنكحي الذي لا يصلي أو يشرب الخمر أو .. تجتنبه، تلتمس الطيب، فهكذا الرجل يطلب المرأة الصالحة المعروفة بالدين والاستقامة والمحافظة على الصلاة حتى تستقيم العشرة بينهما على خير وهدى، وهكذا حتى تكون الذرية إن شاء الله كذلك صالحة. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12561/حكم-مخالفة-الوالدين-في-خطبة-فتاة-لا-تصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_615/61502.mp3","categories":["حكم الصلاة وأهميتها","الخِطْبَة والاختيار "]},{"id":14408,"question":"يقول هذا السائل أبو مجاهد، مقيم في الإمارات العربية المتحدة، يقول: لي رغبة أن أتحدث مع خطيبتي ليس لها أخ، ووالدها مشغول في عمله، ولا يأتي إلى البيت إلا في وقت متأخر، هل تعتبر هذه خلوة إذا كانت معنا أختها أو أمها؟","title":"حكم تحدث الرجل مع مخطوبته","answer":"الجواب: لا، ليست خلوة، لكن إذا كنت قد عقدت عليها فهي زوجة، أما إذا كنت ما عقدت عليها فأنت تنظر إليها عند الحاجة، وإذا كنت نظرت إليها، واقتنعت بأنها مناسبة، فلا حاجة إلى النظر الثاني، يكفي النظر الأول الذي حصل به القناعة والفائدة، وعزمت على خطبتها، أما إذا كنت قد تزوجتها، فالحمد لله، وإذا كان معك أمها أو أختها أو عمها أو خالها فليست خلوة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12890/حكم-تحدث-الرجل-مع-مخطوبته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_553/55305.mp3","categories":["الخِطْبَة والاختيار ","قضايا المرأة"]},{"id":14685,"question":"يقول السائل سالم غانم من الأردن: هل يجوز أن يجلس الخطيب مع خطيبته بعد العقد وقبل الدخول؟","title":"حكم الجلوس مع المخطوبة بعد العقد","answer":"الجواب: نعم، زوجته له أن يجلس معها، وينظر إليها، ويخلو بها، لا بأس زوجته، لكن إذا كان يخشى أو تخشى شيئًا من أهلها لا يفعل، لا يعرضها لشيء من الشر إلا بإذن أهلها، حتى تكون الخلوة شرعية.  أما إذا كان أهلها يسمحون بذلك فلا بأس أن يخلو بها؛ لأنها زوجته بعد العقد، أما قبل العقد لا، ليس له أن يخلو بها، له أن ينظر إليها، لكن ليس له أن يخلو بها قبل العقد.  أما بعد العقد إذا سمح له أهلها فلا بأس، وإلا فليصبر حتى يأتي الزفاف المعروف والمعتاد. المقدم: جزاكم الله خيرًا، وأحسن إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13174/حكم-الجلوس-مع-المخطوبة-بعد-العقد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_560/56012.mp3","categories":["الخِطْبَة والاختيار ","قضايا المرأة"]},{"id":15518,"question":"هذه سائلة من القوارة تقول: بأنها فتاة تقدم لها الكثير من الشباب، ولكنها ترفض بسبب أنها تريد -يا سماحة الشيخ- رجل ملتزم بجميع الأوامر، والآن تقدم لها شاب، ولكنه يشرب الدخان، هل ترفض أم توافق؟ تريد من سماحة الشيخ توجيه.","title":"توجيه لمن تقدم لخطبتها شاب مدخن","answer":"الجواب: لا مانع من الزواج به، ولكن إذا تيسر غيره فهو الأحسن والأكمل، لكن إذا خشيت أن تتعطل، فكونها تتزوج بمسلم لكنه يدخن أولى من تعطلها، ولكن متى تيسر لها من هو سليم من الدخان فهو الأحوط لها؛ لأن الدخان محرم خبيث، ومضرته عظيمة، نعم.","link":"https://binbaz.org.sa/fatwas/14055/توجيه-لمن-تقدم-لخطبتها-شاب-مدخن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_569/56917.mp3","categories":["قضايا المرأة","الخِطْبَة والاختيار "]},{"id":15641,"question":"أريد أن أتزوج فما هو رأي سماحتكم في الشروط التي اشترطها في المخطوبة، ما هي؟وجهوني، جزاكم الله خيرًا.","title":"صفات الزوجة التي ينبغي اختيارها","answer":"الجواب: عليك بذات الدين، عليك بالمرأة الصالحة المعروفة بالأخلاق الطيبة، بالصلاة والعفاف، وطيب الخلق، وطيب الكلام، وحسن الصورة أيضًا؛ لقوله ﷺ: تنكح المرأة لأربع: لمالها ولجمالها ولحسبها ولدينها؛ فاظفر بذات الدين تربت يداك. فأوصى بذات الدين، فنوصيك بما أوصى به النبي ﷺ، ذات الدين، نوصيك بالمرأة المعروفة بالاستقامة بالصلاة في وقتها بالعفة عما حرم الله، بطيب اللسان، وطيب الكلام، بالأخلاق الكريمة، وحسن الخلق، وإذا تيسر مع هذا الجمال والنسب الحسن والمال؛ هذا خير إلى خير، ولكن المهم أن تكون أخلاقها كريمة، محافظة على الدين، طيبة في الصلاة، طيبة في أخلاقها، بعيدة عما حرم الله من الفواحش، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14181/صفات-الزوجة-التي-ينبغي-اختيارها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_705/nour_70509.mp3","categories":["نصائح وتوجيهات","الخِطْبَة والاختيار ","نكاح الكفار"]},{"id":15947,"question":"المستمع محمد علي حسن بعث برسالة وضمنها سؤالًا واحدًا، يقول فيه: هل يحق أن أكلم مخطوبتي أو أن أتحدث معها؟ وما هي نصيحتكم لكل مخطوبين؟","title":"حكم تحدث الخاطب إلى المخطوبة","answer":"الجواب: نعم، لا حرج في التحدث مع المخطوبة من طريق الهاتف، أو من طريق المباشرة عند وجود محرمها، أو غيره على وجه ليس فيه تهمة، وليس فيه خلوة إذا كان الحديث في مصلحة الزواج، لا بأس في ذلك.  أما إذا كان الحديث قد يجر إلى منكر، أو إلى فاحشة فلا يجوز، لكن إذا كان في مصلحة الزواج، وليس فيه خلوة، بل من بعيد بالهاتف، أو بحضور أبيها أو أخيها أو أمها أو نحو ذلك فلا حرج في ذلك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14553/حكم-تحدث-الخاطب-الى-المخطوبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_746/nour_74608.mp3","categories":["الخِطْبَة والاختيار ","قضايا المرأة"]},{"id":15997,"question":"على بركة الله، نبدأ هذا اللقاء برسالة وصلت من السائلة جيهان من المنطقة الشرقية، لها مجموعة من الأسئلة، تقول في السؤال الأول -يا سماحة الشيخ-: هل يجوز للمرأة أن تدعو لنفسها بالزوج الصالح والصفات التي ترغبها في هذا الزوج؟","title":"حكم دعاء المرأة أن ييسر لها الله الزوج الصالح","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه. \nنعم، يشرع لها هذا، يشرع لها أن تطلب ربها أن يسهل لها الزوج الصالح، كالرجل يسأل ربه أن يسهل له الزوجة الصالحة، هذا من الدعاء الطيب، هي تسأل ربها أن الله ييسر لها الزوج الصالح، والرجل كذلك يسأل الله أن يسهل له الزوجة الصالحة، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/14606/حكم-دعاء-المراة-ان-ييسر-لها-الله-الزوج-الصالح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_579/57901.mp3","categories":["الخِطْبَة والاختيار ","قضايا المرأة"]},{"id":16272,"question":"من بيشة رسالة بعث بها إحدى الأخوات المستمعات تقول: (ع. ع. س) من سد وادي بيشة تقول: إنه يوجد في منطقتنا نساء، ونحن بادية، ويفد إلى هؤلاء النساء ضيوف؛ فتقوم المرأة بتكريم الضيوف إذا كان زوجها غائبًا، أو متوفيًا، وإذا كانت مطلقة، وليس هناك -بحمد الله- شك ولا ريبة، فهل في هذا شيء؟ وبم توجهون الناس؟ جزاكم الله خيرًا.","title":"حكم استقبال المرأة الضيوف وإكرامهم","answer":"الجواب: إذا كان الموضوع ليس فيه ريبة، ولا خلوة؛ فلا مانع أن تقدم لهم الضيافة، وهي متسترة، متحفظة في وجهها، ويديها، وبدنها، تقدم لهم، وتقول لهم: خذوا عندكم القهوة ،عندكم كذا، تقهووا، وافعلوا كذا.. وكلوا.. تقدم لهم الطعام، وهم يأخذونه، والحمد لله. أما إذا كان واحدًا؛ لا تخلو به، تعذر تقول: ليس عندي أحد، واعذرني يا أخي! وكذلك إذا كان هناك ريبة، تخشى ريبة؛ تعتذر إليهم، ولو كانوا أكثر من واحد، إذا كانت تخشى أن تتهم بالشر؛ فتعتذر إليهم، وتقول: اعذروني؛ صاحب البيت ليس بحاضر، إن شاء الله تراجعونه في وقت كذا، وفي وقت كذا، أما إذا كان طوفًا معروفًا عندهم، وليس فيه تهمة، ولا شر، تقدم لهم ما ينبغي من الضيافة، مع التستر، والتحفظ، والكلام الطيب، والحمد لله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14973/حكم-استقبال-المراة-الضيوف-واكرامهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_752/nour_75210.mp3","categories":["الخِطْبَة والاختيار ","النظر والخلوة والاختلاط","قضايا المرأة","الآداب والأخلاق المحمودة"]},{"id":16286,"question":"من بيشة رسالة بعث بها إحدى الأخوات المستمعات تقول: (ع. ع. س) من سد وادي بيشة تقول: إنه يوجد في منطقتنا نساء، ونحن بادية، ويفد إلى هؤلاء النساء ضيوف؛ فتقوم المرأة بتكريم الضيوف إذا كان زوجها غائبًا، أو متوفيًا، وإذا كانت مطلقة، وليس هناك -بحمد الله- شك ولا ريبة، فهل في هذا شيء؟ وبم توجهون الناس؟ جزاكم الله خيرًا.","title":"حكم استقبال المرأة الضيوف وإكرامهم","answer":"الجواب: إذا كان الموضوع ليس فيه ريبة، ولا خلوة؛ فلا مانع أن تقدم لهم الضيافة، وهي متسترة، متحفظة في وجهها، ويديها، وبدنها، تقدم لهم، وتقول لهم: خذوا عندكم القهوة ،عندكم كذا، تقهووا، وافعلوا كذا.. وكلوا.. تقدم لهم الطعام، وهم يأخذونه، والحمد لله. أما إذا كان واحدًا؛ لا تخلو به، تعذر تقول: ليس عندي أحد، واعذرني يا أخي! وكذلك إذا كان هناك ريبة، تخشى ريبة؛ تعتذر إليهم، ولو كانوا أكثر من واحد، إذا كانت تخشى أن تتهم بالشر؛ فتعتذر إليهم، وتقول: اعذروني؛ صاحب البيت ليس بحاضر، إن شاء الله تراجعونه في وقت كذا، وفي وقت كذا، أما إذا كان طوفًا معروفًا عندهم، وليس فيه تهمة، ولا شر، تقدم لهم ما ينبغي من الضيافة، مع التستر، والتحفظ، والكلام الطيب، والحمد لله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14973/حكم-استقبال-المراة-الضيوف-واكرامهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_752/nour_75210.mp3","categories":["الخِطْبَة والاختيار ","النظر والخلوة والاختلاط","قضايا المرأة","الآداب والأخلاق المحمودة"]},{"id":16331,"question":"مع بداية هذه الحلقة نعود إلى رسالة وصلت إلى البرنامج من المستمع عبدالرحيم أحمد من أبو ظبي، الأخ عبدالرحيم عرضنا بعض أسئلة له في حلقة مضت، وفي هذه الحلقة يسأل ويقول: إذا خطب الإنسان من أناس، فهل له أن يذهب إلى بيتهم ليزورهم من أجل أن يتم الاتفاق على كل شيء؟ وكذلك من أجل أن تحصل الألفة بين العروسين؟ وجهونا جزاكم الله خيرًا.","title":"حكم زيارة الخاطب أهل المخطوبة","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فلا حرج في الزيارة من الخطيب إلى أهل المخطوبة، لا بأس بذلك إذا كان في ذلك مصلحة للخاطب والمخطوبة، للتعرف، ولمعرفة أحوال الجميع، وللتعاون على البر والتقوى، المقصود: أنه لا حرج في الزيارة للمصلحة، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15027/حكم-زيارة-الخاطب-اهل-المخطوبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_754/nour_75401.mp3","categories":["الخِطْبَة والاختيار ","نصائح وتوجيهات"]},{"id":16550,"question":"رسالة وصلت إلى البرنامج من المستمع، عبدالرحيم أحمد من أبو ظبي يسأل فيها سؤالًا فيقول: قام شاب بخطبة شابة من أهلها، وقاموا بقراءة الفاتحة بينهم؛ لتكون ارتباطًا بينهما، وبعد أسبوعين سافر هذا الشاب إلى إحدى الدول العربية للعمل بها ...الشيخ: أعد، أعد.المقدم: يقول: قام شاب بخطبة شابة من أهلها، وقاموا بقراءة الفاتحة بينهم؛ لتكون ارتباطًا بينهما، وبعد أسبوعين سافر هذا الشاب إلى إحدى الدول العربية للعمل بها، فهل يجوز لهذا الشاب أن يراسلها وتراسله من أجل أن يتفهم كل منهم الآخر، ومن أجل تقريب نظرية كل منهم للآخر؟ جزاكم الله خيرًا.","title":"حكم قراءة الفاتحة عند الخطبة، ومراسلة المخطوبة","answer":"الجواب: قراءة الفاتحة ما لها أصل... بينهما ليس لهذا أصل، الخطبة وحدها ما تكفي، وقراءة الفاتحة لا وجه لها في هذا المقام، وإنما تقرأ الفاتحة، والحمد عند العقد، إذا أراد العقد يقرأ السنة ما هو الفاتحة، يقرأ: إن الحمد لله نحمده ونستعينه... كما كان النبي ﷺ يفعل في الحاجة، خطبة الحاجة، ما هو يقرأ الفاتحة، يقرأ: إن الحمد لله.. إلى آخره، كما جاءت به السنة من حديث ابن مسعود في خطبة الحاجة، أما هذه فهذه من خرافات العامة، ومن أعمال العامة، إذا قرأ الفاتحة للربط بينهما، هذا ما له أصل، كلام ما له أصل، إنما الخطبة لا بأس بها، وكل منهم بالخيار، الخطبة ما تلزمهم، من شاء ترك هون. من شاء هون هي تهون، وهم يهونون كل من شاء منهم التهوينة له يهون لا بأس، إنما العمدة على العقد. أما المراسلة بعد الخطبة كونه يراسلها، ويسألها عن حالها وعن دروسها، أو عن كذا عن شيء ينفع، أو تراسله لتسأل عن شيء مهمات، مراسلة ما فيها خطر، ما فيها شر، ولا تدعو إلى خلوة، ولا تدعو إلى فساد، ولا زنا، هذا لا بأس. أما إذا كانت مراسلة قد يخشى منها الشر؛ فلا ينبغي أن يراسلها، ولا ينبغي أن تراسله، وينبغي سد الباب حتى لا يتهموا بالشر.  لكن إذا كانت المراسلة واضحة يعرفها أهلهما، ليس فيها شبهة، ولا توقع في شبهة، إنما هي لحاجتهما للتفاهم في بعض المسائل؛ فلا بأس بذلك، نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15290/حكم-قراءة-الفاتحة-عند-الخطبة-ومراسلة-المخطوبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_757/nour_75714.mp3","categories":["الخِطْبَة والاختيار ","نصائح وتوجيهات"]},{"id":16817,"question":"سماحة الشيخ! يقول هذا السائل: شخص خطب فتاة، وأهل هذه الفتاة منعوه من الجلوس معها، والتحدث إليها، أو حتى النظر إليها، إذا خطب الرجل امرأة هل له أن ينظر إليها في حضور أقاربها؟","title":"حكم نظر الرجل إلى مخطوبته","answer":"الجواب: السنة النظر، الرسول ﷺ أمر من خطب أن ينظر، قال: إن استطاع أن ينظر إلى ما يدعوه إلى نكاحها؛ فليفعل. المقصود: أنه أمر من خطب أن ينظر، وقال له رجل: «يا رسول الله! إني خطبت فلانة، قال: هل نظرت إليها؟ قال: لا، قال: اذهب فانظر إليها وقال: إذا خطب أحدكم المرأة، فإن استطاع أن ينظر منها إلى ما يدعوه إلى نكاحها؛ فليفعل. فالسنة أن ينظر إلى المخطوبة حسب التيسير، لكن لا يخلو بها، إنما يستحب له أن ينظر إليها بحضرة أخيها، أو أمها، أو غيرهم، أو من بعيد؛ لعله يرى منها ما يدعوه إلى نكاحها، فإن تزوجها، ولم ينظر إليها؛ فلا حرج، وإن تيسر أن يرسل إليها من ينظر إليها، ويعرف حالها، ثم يخبره بصفاتها؛ فهذا يكفي عن النظر. المقصود: أن السنة أن يتثبت في الأمر، هذا السنة، الخاطب يتثبت بالنظر، أو بإرسال من يطمئن إليها حتى ينظر إليها من أمه، أو أخته، أو بنته، أو نحو ذلك؛ حتى تفيده عن صفاتها، وأخلاقها، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/15557/حكم-نظر-الرجل-الى-مخطوبته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_585/58514.mp3","categories":["الخِطْبَة والاختيار ","نصائح وتوجيهات"]},{"id":16835,"question":"رسالة من الرياض، وباعثتها إحدى الأخوات المستمعات تقول: السائلة (و. م. خ) لها جمع من الأسئلة في أحدها تقول: لي أخ يريد الزواج من امرأة معينة، وهو شاب يخشى عليه، لكنه طلب منا نحن إخواته تمكينه من رؤيتها، دون علمها؛ شرط ألا يخل هذا بحكم الله  وذلك حتى لا يقع الحرج له، أو لها إذا كان رأيه ألا يتزوج بها، فما الحكم هنا؟ وما السبيل إلى ذلك؟ مع العلم بأننا -والحمد لله- محافظون على تطبيق ما يرضى عنه الله .","title":"جواز النظر للمخطوبة دون علمها","answer":"الجواب: لا حرج في ذلك: أن تسعين في تمكينه من رؤيتها من دون خلوة، كأن تعزمها إحداكن، ثم ينظر إليها من باب، أو هوة، أو غير ذلك، وهي معكن، لا حرج في ذلك، النبي ﷺ رخص للصحابة أن ينظروا في المخطوبة، كان جابر لما أراد أن يتزوج امرأة جعل يتخبأ لها؛ حتى ينظر إليها. فالمقصود: إذا كان النظر من دون خلوة؛ فلا حرج في ذلك، إذا كان يريد خطبتها، نعم. المقدم: جزاكم الله خيرًا، إنما بشرط أن يكون مريدًا للخطبة؟ الجواب: نعم، لا بد أن يكون مريدًا، وإلا فلا يجوز. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15623/جواز-النظر-للمخطوبة-دون-علمها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_824/nour_82417.mp3","categories":["الخِطْبَة والاختيار ","نصائح وتوجيهات"]},{"id":16850,"question":"رسالة من الرياض، وباعثتها إحدى الأخوات المستمعات تقول: السائلة (و. م. خ) لها جمع من الأسئلة في أحدها تقول: لي أخ يريد الزواج من امرأة معينة، وهو شاب يخشى عليه، لكنه طلب منا نحن إخواته تمكينه من رؤيتها، دون علمها؛ شرط ألا يخل هذا بحكم الله  وذلك حتى لا يقع الحرج له، أو لها إذا كان رأيه ألا يتزوج بها، فما الحكم هنا؟ وما السبيل إلى ذلك؟ مع العلم بأننا -والحمد لله- محافظون على تطبيق ما يرضى عنه الله .","title":"جواز النظر للمخطوبة دون علمها","answer":"الجواب: لا حرج في ذلك: أن تسعين في تمكينه من رؤيتها من دون خلوة، كأن تعزمها إحداكن، ثم ينظر إليها من باب، أو هوة، أو غير ذلك، وهي معكن، لا حرج في ذلك، النبي ﷺ رخص للصحابة أن ينظروا في المخطوبة، كان جابر لما أراد أن يتزوج امرأة جعل يتخبأ لها؛ حتى ينظر إليها. فالمقصود: إذا كان النظر من دون خلوة؛ فلا حرج في ذلك، إذا كان يريد خطبتها، نعم. المقدم: جزاكم الله خيرًا، إنما بشرط أن يكون مريدًا للخطبة؟ الجواب: نعم، لا بد أن يكون مريدًا، وإلا فلا يجوز. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15623/جواز-النظر-للمخطوبة-دون-علمها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_824/nour_82417.mp3","categories":["الخِطْبَة والاختيار ","نصائح وتوجيهات"]},{"id":16989,"question":"تقول: سمعت بأنه يجب على الفتاة ألا تتزوج إلا من رجل مظهره إسلامي، وأنا والحمد لله فتاة ملتزمة إلا أن جميع من يتقدم لي غير ملتزم، فهل أوافق، أم لا؟","title":"الأولى والأكمل للمرأة الزواج ممن مظهره إسلامي","answer":"الجواب: لا حرج عليك.. الموافقة إذا كان مسلمًا، وإن كان عنده بعض القصور في بعض المعاصي؛ لئلا تتعطلي؛ لأن التماس الكامل اليوم فيه صعوبة كبيرة. فإذا تيسر من هو معروف بالاستقامة على الصلاة، والأخلاق الفاضلة، وإن كان عنده بعض النقص؛ فإنه لا بأس أن تتزوجيه، وأن تعفي نفسك، والحمد لله. لكن إذا تيسر الرجل المعروف بالاستقامة، وعدم وقوع شيء من المعاصي، هذا أكمل وأطيب، ومن أمثلة ذلك: أن يكون يتعاطى التدخين، أو يتعاطى الإسبال، أو يتعاطى شيئًا، قص من لحيته، أو ما أشبه ذلك، هذا نقص ومعصية، لكن إذا تيسر غيره فهو مطلوب وهو الأكمل.  وإذا لم يتيسر إلا هذا الصنف من الناس فلا حرج في الزواج للعفة، وسلامة الدين، والعرض؛ ولعل الله يهديه بأسبابك. نعم. المقدم: الله المستعان، المظهر الإسلامي الكامل كيف يكون سماحة الشيخ؟ الشيخ: المظهر الإسلامي يكون على الطريقة المحمدية، على حسب ظاهر الشرع في ملبسه، وفي مشيه، وفي جميع شؤونه، معروفًا بعدم الإسبال، عدم حلق اللحى، أو تقصيرها، عدم التكبر، محافظ على الصلوات.. في جماعة إلى غير ذلك من مظاهر الإسلام، نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15787/الاولى-والاكمل-للمراة-الزواج-ممن-مظهره-اسلامي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_829/nour_82911.mp3","categories":["الخِطْبَة والاختيار ","قضايا المرأة"]},{"id":17213,"question":"تسأل سماحتكم عن محبة الشخص من أجل الزواج منه؟","title":"حب المرأة للرجل قبل الزواج","answer":"الجواب: لا بأس المحبة كونها تحبه في الله، أو تحبه لأنها ترغب في الزواج منه، لأسباب اقتضت ذلك؛ لقرابة، أو ديانة، أو أسباب أخرى، لكن ليس لها أن تعمل معه إلا ما أباح الله، ليس لها أن تعمل معه شيئًا مما حرم الله، بل تسعى في الزواج به إذا كان صاحب دين، وصاحب خير، أو مستورًا ليس به بأس؛ فلا بأس أن تسعى في الزواج منه بالطرق الشرعية، من دون خلوة به؛ حتى يتم الزواج. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/16039/حب-المراة-للرجل-قبل-الزواج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_723/nour_72309.mp3","categories":["الخِطْبَة والاختيار ","قضايا المرأة"]},{"id":17370,"question":"في آخر أسئلة هذا السائل يقول: سماحة الشيخ هل يحق لي أن آخذ رأي والدي في البحث عن زوجة، وبدون أن أراها، أو أعرفها؟","title":"أفضلية مشاورة الأب في اختيار الزوجة","answer":"الجواب: الأفضل أن تشاور أباك، هذا من الأدب، ومن البر أن تشاوره فيمن تخطب، تقول: يا والدي! ممكن أريد فلانة، تشاور فيه، وتشاور من يعلمها من أهل الخير، ولا تعجل حتى تطمئن إلى أنها طيبة صالحة لقوله ﷺ: تنكح المرأة لأربع: لمالها، ولجمالها، ولحسبها، ولدينها، فاظفر بذات الدين تربت يداك تسأل عن دينها، وعن أخلاقها، وعما يتعلق بالترغيب فيها؛ حتى تقدم على بصيرة. ويستحب لك النظر إليها، إذا تيسر النظر تنظر إليها بإذن أهلها، أو بغير إذن، إذا تيسر النظر إليها، ولو بغير إذن أهلها في من كوة.. من باب.. من جهة أخرى، وهي في المرعى، من غير خلوة قال جابر  \"خطب امرأة، فلم يزل يتخبأ حتى نظر إليها\" والنبي ﷺ قال: إذا خطب أحدكم المرأة فإن استطاع أن ينظر منها إلى ما يدعوه إلى نكاحها فليفعل وقال لرجل تزوج امرأة: أنظرت إليها؟ قال: لا، قال: اذهب فانظر إليها. فالمقصود: النظر إليها مستحب إذا تيسر، ولو من دون علمها، لكن من دون خلوة، كأن ينظرها من بعيد، وهي في غنمها، أو في مجلس عند أهلها، أو ما أشبه ذلك. المقدم: أحسن الله إليكم، وبارك فيكم.","link":"https://binbaz.org.sa/fatwas/16232/افضلية-مشاورة-الاب-في-اختيار-الزوجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_770/nour_77009.mp3","categories":["حكم الصلاة وأهميتها","الخِطْبَة والاختيار ","بر الوالدين"]},{"id":17374,"question":"في آخر أسئلة هذا السائل يقول: سماحة الشيخ هل يحق لي أن آخذ رأي والدي في البحث عن زوجة، وبدون أن أراها، أو أعرفها؟","title":"أفضلية مشاورة الأب في اختيار الزوجة","answer":"الجواب: الأفضل أن تشاور أباك، هذا من الأدب، ومن البر أن تشاوره فيمن تخطب، تقول: يا والدي! ممكن أريد فلانة، تشاور فيه، وتشاور من يعلمها من أهل الخير، ولا تعجل حتى تطمئن إلى أنها طيبة صالحة لقوله ﷺ: تنكح المرأة لأربع: لمالها، ولجمالها، ولحسبها، ولدينها، فاظفر بذات الدين تربت يداك تسأل عن دينها، وعن أخلاقها، وعما يتعلق بالترغيب فيها؛ حتى تقدم على بصيرة. ويستحب لك النظر إليها، إذا تيسر النظر تنظر إليها بإذن أهلها، أو بغير إذن، إذا تيسر النظر إليها، ولو بغير إذن أهلها في من كوة.. من باب.. من جهة أخرى، وهي في المرعى، من غير خلوة قال جابر  \"خطب امرأة، فلم يزل يتخبأ حتى نظر إليها\" والنبي ﷺ قال: إذا خطب أحدكم المرأة فإن استطاع أن ينظر منها إلى ما يدعوه إلى نكاحها فليفعل وقال لرجل تزوج امرأة: أنظرت إليها؟ قال: لا، قال: اذهب فانظر إليها. فالمقصود: النظر إليها مستحب إذا تيسر، ولو من دون علمها، لكن من دون خلوة، كأن ينظرها من بعيد، وهي في غنمها، أو في مجلس عند أهلها، أو ما أشبه ذلك. المقدم: أحسن الله إليكم، وبارك فيكم.","link":"https://binbaz.org.sa/fatwas/16232/افضلية-مشاورة-الاب-في-اختيار-الزوجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_770/nour_77009.mp3","categories":["حكم الصلاة وأهميتها","الخِطْبَة والاختيار ","بر الوالدين"]},{"id":17450,"question":"يقول هذا السائل: سماحة الشيخ! والدي هداه الله لا يصلي في المسجد، وإنما يصلي في البيت، ناصحته كثيرًا، فهل علي إثم تجاه والدي؟ وبماذا تنصحونني أن أفعل مأجورين؟","title":"واجب الابن تجاه أبيه التارك لصلاة الجماعة","answer":"الجواب: عليك أن تنصحه بالكلام الطيب، والأسلوب الحسن، ولا تقطع الزيارة؛ لأن حقه عظيم، قال الله في حق الولد مع الكافرين: وَصَاحِبْهُمَا فِي الدُّنْيَا مَعْرُوفًا [لقمان:15] وهما كافران حق، الوالد عظيم، تزوره، تدعو له بالتوفيق والهداية، توصيه بالصلاة في المسجد، وأبشر بالخير، ولا تفعل بشيء يؤذيه من كلام سيئ، أو وجه معبس، لا، انبسط إليه، وتكلم معه، وانصحه، وادع له بالهداية، والتوفيق، ولا تقطع زيارته، حقه عظيم الوالد والوالدة، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16319/واجب-الابن-تجاه-ابيه-التارك-لصلاة-الجماعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_772/nour_77207.mp3","categories":["حكم الصلاة وأهميتها","الخِطْبَة والاختيار ","بر الوالدين"]},{"id":17769,"question":"ما حكم لبس الدبلة الذهب بالنسبة للمرأة لإعلان الخطبة ولبس الدبلة الفضة للرجل لنفس السبب؟","title":"حكم دبلة الخطوبة للرجل والمرأة","answer":"الجواب: لا أعلم لهذا أصلًا، لا أعلم لهذا أصلًا، وإذا كان في بلد اعتادوه فلا أعلم به بأسًا، أما أن ينشئه جديدًا ويسنه للناس فلا أصل له، لكن إذا أوجد في بلد واعتادوه فلا أعلم به بأسًا وإلا فالأصل ترك ذلك؛ لئلا يتشبه بأعداء الله إذا كان من أخلاق أعداء الله، أما إذا كان المسلمون فعلوه واعتادوه في أي بلد في أي قرية زالت المشابهة. نعم.\nالمقدم: أحسن الله إليكم وجزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16753/حكم-دبلة-الخطوبة-للرجل-والمراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_778/nour_77803.mp3","categories":["الخِطْبَة والاختيار ","البدع والمحدثات"]},{"id":18158,"question":"رسالة وصلت إلى البرنامج من الأخ المستمع يوسف مستور حمدان من السودان النيل الأبيض ويعمل حال كتابة رسالته في العراق، أخونا يسأل عن زواج من أسرة جميع أفرادها يشربون الخمر ولا يعلم عن ذلك إلا بعد أن تقدم للخطبة؟","title":"حكم الزواج من أسرة أفرادها يشربون الخمر","answer":"الجواب: هذا ينبني على معرفة حال البنت المخطوبة، إذا كانت على طريقة أهلها فينبغي تركها، أما إذا كانت معروفة بالاستقامة وترك ما عليه أهلها فلا بأس بأخذها، وإذا كان يجهل ذلك فالحيطة له أن لا يتزوج منهم لئلا تكون مثلهم. نعم. المقدم: جزاكم الله خيرًا! أيضًا عن الصلاة سماحة الشيخ يقول: إنهم لا يصلون. الشيخ: كذلك ينظر ويسأل فإن ثبت أنها مستقيمة وأنها قد خالفت أهلها وتصلي ولا تشرب الخمر فلا بأس، لا يضرها وَلا تَزِرُ وَازِرَةٌ وِزْرَ أُخْرَى [الأنعام:164]، أما إن كانت مثل أهلها أو لا يدري عنها فينبغي له تجنب ذلك حتى يحتاط لدينه وحتى يسلم من تزوج امرأة غير دينة. نعم. المقدم: جزاكم الله خيرًا، إذًا يلزم الإنسان والحالة هذه أن يسأل عن الأسرة التي يريد... الشيخ: نعم، ينبغي له التبصر وعدم العجلة، يقول ﷺ: تنكح المرأة لأربع: لمالها، ولجمالها، ولحسبها، ولدينها، فاظفر بذات الدين تربت يداك ولا يمكن أن يعرف ذات الدين إلا بالسؤال، سؤال الثقات العارفين بها. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17203/حكم-الزواج-من-اسرة-افرادها-يشربون-الخمر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_905/nour_90511.mp3","categories":["الخِطْبَة والاختيار ","نصائح وتوجيهات"]},{"id":18514,"question":"سؤالها الأخير أم بلال من اليمن تقول: لدي سؤال أنني زوجت أختي، أو بمعنى أصح: كنت واسطة في زواجها في بيت كثر فيه الفساد، وقد كانت أختي تعلم ذلك قبل زواجها بهذا الأمر، وحتى الآن هي مقتنعة بذلك، ولكن ضميري يؤنبني على ذلك، فهل أنا آثمة في توسطي لهذا الزواج لأختي؟أفيدونا سماحة الشيخ.","title":"أعانت على تزويج أختها لأهل بيت كثر فيه الفساد","answer":"الجواب: الواجب على المؤمن أن ينصح لأخيه في الله وأخته في الله ولأخيه في النسب وأخته في النسب، وأن يتقي الله في ذلك، فإذا كنت توسطت في زواجها بإنسان يضرها في دينها، فهذا غلط منك عليك التوبة إلى الله. وأما إذا كنت توسطت لأنك ترين أنه مناسب، ولا حرج فيه، ولكن جاء الفساد بعد ذلك، فلا يضرك، الواجب على الناصح أن يتقي الله، وأن لا ينصح، وأن لا يشير إلا بالشيء الذي يبرئ الذمة، وليس فيه محذور شرعًا، وليس لك أن تشيري بزوج غير مستقيم؛ لأنه يضر الزوجة، فإذا كان هذا الزوج غير مستقيم، وأنت تعلمين أنه غير مستقيم، فقد أخطأت، وعليك التوبة إلى الله ، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17609/اعانت-على-تزويج-اختها-لاهل-بيت-كثر-فيه-الفساد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_786/nour_78611.mp3","categories":["الخِطْبَة والاختيار ","نصائح وتوجيهات"]},{"id":18613,"question":"سماحة الشيخ: ما رأيكم فيمن تقدم لها أكثر من خاطب؟","title":"معيار قبول الخاطب وبيان عيوب المخطوبة","answer":"الجواب: عليها أن تختار الأتقى لله، من بلغ عنه أنه أتقى لله، وأحسن دينًا، وأكمل دينًا تختاره، وتبين له حالها؛ لأن الرسول ﷺ قال: من غشنا فليس منا تبين له حالها أن معها عرجة قليلة، أو غيره، إن كانت عندها عيوب أخرى تبين له حالها، تبين حالها، لا تغشه: من غشنا فليس منا وعليها أن تختار الطيب من الخاطبين، الطيب في دينه من الخاطبين، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/17720/معيار-قبول-الخاطب-وبيان-عيوب-المخطوبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_918/nour_91820.mp3","categories":["الخِطْبَة والاختيار ","نصائح وتوجيهات"]},{"id":18793,"question":"ما حكم خلع الحجاب أمام الخطيب؟","title":"حكم خلع المخطوبة حجابها أمام الخاطب","answer":"الجواب: لا حرج في ذلك؛ لأن الرسول ﷺ أمر الخطيب أن ينظر إلى المخطوبة، وأخبر أن ذلك أقرب إلى أن يؤدم بينهما، فإذا طلب النظر إليها فلا حرج أن ينظر إليها، وأن تخلع الحجاب حتى يرى وجهها ورأسها، كل هذا لا بأس به، لكن لا يكون عن خلوة، بل يكون عندها غيرها كأمها وأخيها، ونحو ذلك، حتى لا يحصل خلوة، ينظر إليها من دون خلوة، نعم.","link":"https://binbaz.org.sa/fatwas/17915/حكم-خلع-المخطوبة-حجابها-امام-الخاطب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_906/nour_90608.mp3","categories":["الخِطْبَة والاختيار ","نصائح وتوجيهات"]},{"id":18834,"question":"هذه فتاة رمزت لاسمها (مريم . أ. أ) تقول: فتاة ملتزمة تقدم لها رجل لخطبتها، وهو يصلي؛ لكنه يشرب الشيشة، وهي محتارة، وهي ملتزمة أيضًا هل توافق على مثل ذلك أم تنتظر رجلًا صالحًا؟","title":"حكم قبول خطبة شارب الشيشة","answer":"الجواب: الأفضل لها أن تنتظر؛ لأن شرب الشيشة يضرها ويؤذيها، فالأفضل لها أن تنتظر؛ لعل الله ييسر لها زوجًا صالحًا بعيدًا من هذه المعصية، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/17928/حكم-قبول-خطبة-شارب-الشيشة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_791/nour_79114.mp3","categories":["الخِطْبَة والاختيار ","نصائح وتوجيهات"]},{"id":18901,"question":"من العراق رسالة بعثت بها إحدى الأخوات من هناك تقول: (س. س) من العراق، أود فضيلة الشيخ أن أطرح عليكم هذا السؤال، وأرجو أن تجيبوني عليه بأسرع وقت ممكن: هل يحق للرجل أن يخلو بالمرأة بعد أن خطبها، وقد كانت هذه الخطبة بوجود أبيه وأبيها، ووجود رجلين آخرين، وقد قال له أبوها: قد قبلت أن أزوجك ابنتي، وقد حدث هذا بوجود أبيه ورجلين آخرين، وبوجود الشاب أيضًا، فهل يعتبران زوجين حتى لو لم يتم تسجيل هذا العقد في محكمة شرعية؟أفيدونا أفادكم الله.","title":"حكم خلوة الخاطب بمخطوبته","answer":"الجواب: أما مجرد الخطبة، فليس له أن يخلو بها لمجرد الخطبة؛ لأنها أجنبية، وفي خلوته بها خطر، وربما وقع في الفاحشة، والنبي ﷺ قال: لا يخلون رجل بامرأة إلا مع ذي محرم وقال -عليه الصلاة والسلام-: لا يخلون رجل بامرأة؛ فإن الشيطان ثالثهما. ولكن إذا عقد له أبوها بحضرة شاهدين بأن قال: زوجتك، وقال الشاب: قبلت، وهي راضية بذلك، فإنها زوجته، له أن يخلو بها، وله أن يجامعها، لكن إذا كان ذلك قد يخالف عرف أهل البلد، وربما أفضى إلى سوء الظن بها، وأنها ربما تحمل، ويظن أنه من غير زوجها، فهذا لا ينبغي؛ إبعادًا عن سوء الظن وعن التهم. أما إذا خلا بها بإذن أهلها، وبعلم أهلها، واتصل بها بعد الزواج بعد العقد، فلا بأس بذلك، والأفضل أن يؤجل ذلك حتى يأتي الزفاف، حتى يتم الزفاف المعروف بينهما؛ حتى لا تكون هناك تهمة، وحتى لا يقع خطر في سوء الظن، والله المستعان، نعم.","link":"https://binbaz.org.sa/fatwas/18057/حكم-خلوة-الخاطب-بمخطوبته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_881/nour_88108.mp3","categories":["الخِطْبَة والاختيار ","نصائح وتوجيهات"]},{"id":19228,"question":"يسأل أخونا ويقول: هل لبس دبلة الخطبة من الكبائر أم من الصغائر؟","title":"حكم لبس دبلة الخطوبة","answer":"الجواب: لا شك أنها مكروهة، ولا أصل لها فيما نعلم، فينبغي تركها، أما كونها من الكبائر أو الصغائر فمحل نظر، لكن بكل حال لا ينبغي تعاطيها؛ لأنها مستوردة من الكفرة، فلا وجه لاستعمالها ولا حاجة إليها، متى تم العقد فالحمد لله ولا يحتاج دبلة يلبسها. نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/18412/حكم-لبس-دبلة-الخطوبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_890/nour_89002.mp3","categories":["الخِطْبَة والاختيار ","البدع والمحدثات"]},{"id":19274,"question":"هل الدبلة -الخاتم- الذي يقدمه الخاطب لمخطوبته حلال أم حرام مع الدليل؟ وهل صحيح إنه فكرة نصرانية؟","title":"حكم إهداء الخاطب دبلة لمخطوبته","answer":"الجواب: لا أعلم له أصلًا، ولم يكن من عادة المسلمين، والذي سمعنا أنه من عادة النصارى، وأنه ورد إلى الناس من لبنان وغيره، فالذي أرى أن ترك ذلك هو الذي ينبغي، هو أسلم وأبعد عن مشابهة الكفرة، ولم يبلغنا عن سلفنا الصالح أنهم كانوا يفعلون شيئًا من ذلك، وإنما يخطب المرأة، ثم يقدم ما تيسر من المهر، ويكفي هذا؛ أما الدبلة والشبكة فلا لها أصل. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18458/حكم-اهداء-الخاطب-دبلة-لمخطوبته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_892/nour_89204.mp3","categories":["الخِطْبَة والاختيار ","نصائح وتوجيهات"]}]
